287: function adjacentWalkable(x, y) {
288:   const opts = [
289:     { x, y: y + 1 }, { x: x - 1, y }, { x: x + 1, y }, { x, y: y - 1 },
290:     { x: x - 1, y: y + 1 }, { x: x + 1, y: y + 1 }, { x: x - 1, y: y - 1 }, { x: x + 1, y: y - 1 },
291:   ];
292:   const p = world.player;
293:   return opts.filter((o) => isWalkable(o.x, o.y)).sort((a, b) => (Math.abs(a.x - p.x) + Math.abs(a.y - p.y)) - (Math.abs(b.x - p.x) + Math.abs(b.y - p.y)))[0] || null;
294: }
