296: // ── update ────────────────────────────────────────────────────
297: export function updateWorld(dt, W, H) {
298:   if (!world.zone) return;
299:   if (battleState.active) return;
300:   const p = world.player;
301:   if (!world.paused) {
302:     state.time = (state.time + dt / 240) % 1;
303:     state.playtime += dt;
304:     // movement
305:     if (p.moving) {
306:       p.progress += dt / 155;
307:       if (p.progress >= 1) {
308:         p.progress = 0;
309:         p.px = p.to.x; p.py = p.to.y;
310:         p.x = p.to.x; p.y = p.to.y;
311:         state.pos.x = p.x; state.pos.y = p.y;
312:         p.moving = false;
313:         p.from = null; p.to = null;
314:         onArrive();
315:       } else {
316:         p.px = p.from.x + (p.to.x - p.from.x) * p.progress;
317:         p.py = p.from.y + (p.to.y - p.from.y) * p.progress;
318:       }
319:     } else {
320:       const dir = inputDirection();
321:       if (dir) {
322:         if (p.path.length) p.path = [];
323:         if (p.pending) p.pending = null;
324:         tryMove(dir);
325:       } else if (p.path.length) {
326:         const next = p.path[0];
327:         const [dx, dy] = [next.x - p.x, next.y - p.y];
328:         const dirName = dx > 0 ? 'right' : dx < 0 ? 'left' : dy > 0 ? 'down' : 'up';
329:         if (tryMove(dirName)) p.path.shift();
330:         else p.path = [];
331:       }
332:     }
333:     // camera
334:     const T = tileScale(W, H);
335:     const targetX = p.px * T + T / 2 - W / 2;
336:     const targetY = p.py * T + T / 2 - H / 2 + (H > W ? H * .04 : 0);
337:     world.camx += (clampCam(targetX, world.zone.map.w * T, W) - world.camx) * Math.min(1, dt / 90);
338:     world.camy += (clampCam(targetY, world.zone.map.h * T, H) - world.camy) * Math.min(1, dt / 90);
339:   }
340:   // timers
341:   world.hudAcc += dt;
342:   if (world.hudAcc > 400) {
343:     world.hudAcc = 0;
344:     updateHud(world.zone);
345:     setMinimap(world.zone, world.npcs);
346:     if (state.playtime > 0 && Math.floor(state.playtime) % 60 === 0 && !world.paused) saveGame(true);
347:   }
348:   // prompt
349:   if (!world.paused) updatePrompt();
350: }
