45: const BLOCKED_OBJECTS = new Set(['#', 'T', '^', 'r', 'R', 'f', 'g', 'H', 'h', 'D', 'W', 'L', 'A', 'i', 't', 'n', 'B', 'C', 'o', 'S']);
