47: // ── ground ─────────────────────────────────────────────────────
48: function drawGround(ctx, ch, x, y, T, p, now, tx, ty) {
49:   const h = hash(tx, ty);
50:   let base = p.grass;
51:   if (ch === ',' ) base = shade(p.grass2, 6);
52:   else if (ch === '"') base = p.grass2;
53:   else if (ch === '=') base = p.stone;
54:   else if (ch === '_') base = p.path;
55:   else if (ch === 's') base = '#8a7552';
56:   else if (ch === 'x') base = '#3a3330';
57:   else if (ch === 'b') base = '#554636';
58:   else if (ch === 'w') base = p.water;
59:   else if (ch === '~') base = p.water;
60:   else if (ch === 'v') base = '#431d15';
61:   else if (ch === 'H' || ch === 'h' || ch === 'D' || ch === 'W') base = p.stone2;
62:   else if (ch === 'A' || ch === 'S' || ch === 'o' || ch === 'C' || ch === 'i' || ch === 'f') base = p.grass;
63:   else if (ch === 'P') base = p.stone;
64:   if (!['=', '_', 'b', 'H', 'h', 'D', 'W', 'A', 'P', 'S', 'L'].includes(ch)) {
65:     base = shade(base, Math.round((h - .5) * 12));
66:   }
67:   ctx.fillStyle = base;
68:   ctx.fillRect(x, y, T + 1, T + 1);
69: 
70:   if (ch === '.' || ch === ',' || ch === '"' || ch === 'x' || ch === 's') {
71:     // speckle
72:     if (h > .55) {
73:       ctx.fillStyle = withAlpha(p.detail, ch === 'x' ? .18 : .3);
74:       const n = ch === ',' ? 4 : 2;
75:       for (let i = 0; i < n; i++) {
76:         const hx = hash(tx * 7 + i, ty * 13);
77:         const hy = hash(tx * 3, ty * 17 + i);
78:         ctx.fillRect(x + hx * T, y + hy * T, Math.max(1, T * .045), Math.max(1, T * .045));
79:       }
80:     }
81:     if (ch === ',') {
82:       const sway = Math.sin(now / 700 + tx * .8 + ty * .4) * T * .03;
83:       ctx.strokeStyle = withAlpha(shade(p.detail, 15), .85);
84:       ctx.lineWidth = Math.max(1, T * .04);
85:       for (let i = 0; i < 3; i++) {
86:         const bx = x + T * (.18 + i * .28) + (h - .5) * T * .12;
87:         const by = y + T * .82;
88:         ctx.beginPath();
89:         ctx.moveTo(bx, by);
90:         ctx.quadraticCurveTo(bx + sway, by - T * .22, bx + sway * 1.4 + T * .04, by - T * .4);
91:         ctx.stroke();
92:       }
93:     }
94:     if (ch === '"') {
95:       const cols = ['#d9c07a', '#c98f9a', '#b7c9e0'];
96:       ctx.fillStyle = cols[Math.floor(h * cols.length)];
97:       ctx.beginPath();
98:       ctx.arc(x + T * .35, y + T * .4, T * .05, 0, TAU);
99:       ctx.arc(x + T * .55, y + T * .35, T * .04, 0, TAU);
100:       ctx.arc(x + T * .62, y + T * .55, T * .045, 0, TAU);
101:       ctx.fill();
102:     }
103:     if (ch === 'x' && h > .7) {
104:       ctx.strokeStyle = 'rgba(20,16,16,.35)'; ctx.lineWidth = 1;
105:       ctx.beginPath(); ctx.moveTo(x + T * .2, y + T * .7); ctx.lineTo(x + T * .5, y + T * .6); ctx.lineTo(x + T * .8, y + T * .72); ctx.stroke();
106:     }
107:     return;
108:   }
109:   if (ch === '=' || ch === '_') {
110:     // subtle tiled path
111:     ctx.strokeStyle = ch === '=' ? withAlpha(p.stone2, .55) : withAlpha(p.path2, .5);
112:     ctx.lineWidth = 1;
113:     if (ch === '=') {
114:       ctx.strokeRect(x + .5, y + .5, T - 1, T - 1);
115:       if (h > .8) { ctx.beginPath(); ctx.moveTo(x + T * .3, y + T * .35); ctx.lineTo(x + T * .46, y + T * .52); ctx.stroke(); }
116:     } else if (h > .7) {
117:       ctx.beginPath(); ctx.arc(x + T * .3, y + T * .65, T * .025, 0, TAU);
118:       ctx.arc(x + T * .7, y + T * .3, T * .02, 0, TAU); ctx.stroke();
119:     }
120:     return;
121:   }
122:   if (ch === 'b') {
123:     ctx.fillStyle = '#4b3b2c';
124:     ctx.fillRect(x, y + T * .18, T, T * .64);
125:     ctx.strokeStyle = 'rgba(25,18,12,.5)'; ctx.lineWidth = 1;
126:     for (let i = 1; i < 4; i++) {
127:       ctx.beginPath(); ctx.moveTo(x, y + T * (.18 + i * .16)); ctx.lineTo(x + T, y + T * (.18 + i * .16)); ctx.stroke();
128:     }
129:     ctx.fillStyle = 'rgba(255,255,255,.06)';
130:     ctx.fillRect(x, y + T * .2, T, 1);
131:     return;
132:   }
133:   if (ch === 'w' || ch === '~') {
134:     const deep = ch === '~';
135:     ctx.fillStyle = deep ? p.water : p.water2;
136:     ctx.fillRect(x, y, T + 1, T + 1);
137:     ctx.fillStyle = withAlpha(deep ? p.water2 : '#7fb4b0', deep ? .25 : .35);
138:     const off = Math.sin(now / 900 + tx * .9 + ty * .6);
139:     ctx.globalAlpha = deep ? .3 : .5;
140:     ctx.fillRect(x + T * .15 + off * 3, y + T * .35, T * .4, Math.max(1, T * .035));
141:     ctx.fillRect(x + T * .45 - off * 2, y + T * .68, T * .3, Math.max(1, T * .03));
142:     ctx.globalAlpha = 1;
143:     if (!deep) {
144:       ctx.strokeStyle = withAlpha('#93b87e', .5); ctx.lineWidth = Math.max(1, T * .03);
145:       const sw = Math.sin(now / 800 + tx) * 2;
146:       ctx.beginPath(); ctx.moveTo(x + T * .2, y + T * .85); ctx.lineTo(x + T * .22 + sw, y + T * .6); ctx.stroke();
147:       ctx.beginPath(); ctx.moveTo(x + T * .75, y + T * .8); ctx.lineTo(x + T * .74 + sw, y + T * .58); ctx.stroke();
148:     }
149:     return;
150:   }
151:   if (ch === 'v') {
152:     const glow = .55 + .25 * Math.sin(now / 340 + tx * 1.7);
153:     ctx.fillStyle = '#e0632c';
154:     ctx.globalAlpha = glow;
155:     ctx.fillRect(x + T * .08, y + T * .08, T * .84, T * .84);
156:     ctx.globalAlpha = 1;
157:     ctx.fillStyle = '#ffd08a';
158:     ctx.globalAlpha = .7;
159:     ctx.beginPath(); ctx.arc(x + T * .4, y + T * .5, T * .07, 0, TAU); ctx.fill();
160:     ctx.globalAlpha = 1;
161:     return;
162:   }
163:   if (ch === 'H' || ch === 'h' || ch === 'D' || ch === 'W') {
164:     ctx.fillStyle = ch === 'W' ? shade(p.wall, -45) : p.wall;
165:     ctx.fillRect(x, y, T + 1, T + 1);
166:     if (ch === 'W') {
167:       ctx.strokeStyle = 'rgba(0,0,0,.3)'; ctx.lineWidth = 1;
168:       for (let i = 0; i < 2; i++) {
169:         ctx.beginPath(); ctx.moveTo(x, y + T * (.3 + i * .4)); ctx.lineTo(x + T, y + T * (.3 + i * .4)); ctx.stroke();
170:       }
171:       ctx.beginPath(); ctx.moveTo(x + T * .55, y); ctx.lineTo(x + T * .55, y + T * .3); ctx.stroke();
172:     }
173:   }
174: }
