177: function drawTree(ctx, x, y, T, p, opts = {}) {
178:   const big = opts.big;
179:   const h = hash(x * .017, y * .013);
180:   const cx = x + T * .5 + (h - .5) * T * .12;
181:   const baseY = y + T * .95;
182:   const th = T * (big ? .52 : .36);
183:   ctx.fillStyle = 'rgba(0,0,0,.22)';
184:   ctx.beginPath(); ctx.ellipse(cx, baseY, T * (big ? .42 : .3), T * .1, 0, 0, TAU); ctx.fill();
185:   ctx.fillStyle = p.trunk;
186:   ctx.fillRect(cx - T * .045, baseY - th, T * .09, th);
187:   const sway = Math.sin(performance.now() / 2600 + h * 8) * T * .025;
188:   const leaf = shade(p.leaf, Math.round((h - .5) * 18));
189:   const leaf2 = shade(p.leaf2, Math.round((h - .5) * 16));
190:   const r = T * (big ? .46 : .34);
191:   const top = baseY - th - r * .5;
192:   ctx.fillStyle = leaf;
193:   ctx.beginPath(); ctx.arc(cx - r * .42, top + r * .3, r * .58, 0, TAU); ctx.fill();
194:   ctx.beginPath(); ctx.arc(cx + r * .42, top + r * .32, r * .56, 0, TAU); ctx.fill();
195:   ctx.fillStyle = leaf2;
196:   ctx.beginPath(); ctx.arc(cx - r * .1 + sway, top - r * .18, r * .7, 0, TAU); ctx.fill();
197:   ctx.beginPath(); ctx.arc(cx + r * .28 + sway, top + r * .02, r * .48, 0, TAU); ctx.fill();
198:   ctx.fillStyle = withAlpha(p.detail, .3);
199:   ctx.beginPath(); ctx.arc(cx - r * .3 + sway, top - r * .28, r * .22, 0, TAU); ctx.fill();
200: }
