355: function drawBrazier(ctx, x, y, T, lit, now) {
356:   const cx = x + T * .5, base = y + T * .82;
357:   ctx.fillStyle = 'rgba(0,0,0,.25)';
358:   ctx.beginPath(); ctx.ellipse(cx, base + 2, T * .22, T * .06, 0, 0, TAU); ctx.fill();
359:   ctx.strokeStyle = '#3f342b'; ctx.lineWidth = T * .05;
360:   ctx.beginPath(); ctx.moveTo(cx - T * .12, base); ctx.lineTo(cx - T * .06, base - T * .28); ctx.moveTo(cx + T * .12, base); ctx.lineTo(cx + T * .06, base - T * .28); ctx.stroke();
361:   ctx.fillStyle = '#4b3f33';
362:   ctx.beginPath(); ctx.ellipse(cx, base - T * .3, T * .2, T * .07, 0, 0, TAU); ctx.fill();
363:   if (lit) {
364:     const flick = .8 + Math.sin(now / 90 + x) * .2;
365:     const glow = ctx.createRadialGradient(cx, base - T * .4, 0, cx, base - T * .4, T * .55);
366:     glow.addColorStop(0, 'rgba(255,170,80,.4)'); glow.addColorStop(1, 'rgba(255,120,40,0)');
367:     ctx.fillStyle = glow; ctx.fillRect(cx - T * .7, base - T * 1.1, T * 1.4, T * 1.4);
