371:     ctx.quadraticCurveTo(cx - T * .14, base - T * .55, cx + Math.sin(now / 140) * T * .03, base - T * .58 * flick);
372:     ctx.quadraticCurveTo(cx + T * .13, base - T * .52, cx + T * .09, base - T * .32);
