374:     ctx.fillStyle = 'rgba(255,120,50,.8)';
375:     ctx.beginPath(); ctx.arc(cx, base - T * .38, T * .06, 0, TAU); ctx.fill();
376:   } else {
377:     ctx.fillStyle = '#2a2420';
378:     ctx.beginPath(); ctx.ellipse(cx, base - T * .31, T * .15, T * .05, 0, 0, TAU); ctx.fill();
379:     ctx.fillStyle = 'rgba(120,70,50,.5)';
