415:   ctx.fillStyle = '#5a564d';
416:   rr(ctx, cx - T * .26, base - T * .3, T * .52, T * .28, 2); ctx.fill();
417:   ctx.fillStyle = '#6d685e';
418:   rr(ctx, cx - T * .22, base - T * .55, T * .44, T * .26, 2); ctx.fill();
