509:   ctx.fillStyle = g; ctx.beginPath(); ctx.arc(cx, cy, T * .34, 0, TAU); ctx.fill();
510:   ctx.fillStyle = '#f4e9b8';
511:   ctx.save(); ctx.translate(cx, cy);
512:   const s = T * .08;
513:   ctx.beginPath(); ctx.moveTo(0, -s * 1.7); ctx.lineTo(s * .5, -s * .4); ctx.lineTo(s * 1.7, 0); ctx.lineTo(s * .5, s * .4); ctx.lineTo(0, s * 1.7); ctx.lineTo(-s * .5, s * .4); ctx.lineTo(-s * 1.7, 0); ctx.lineTo(-s * .5, -s * .4); ctx.closePath(); ctx.fill();
514:   ctx.restore();
515:   if (item === 'moonpetal') {
516:     ctx.fillStyle = 'rgba(200,220,255,.8)';
