527:   ctx.beginPath(); ctx.ellipse(cx, base, T * .34, T * .07, 0, 0, TAU); ctx.fill();
528:   ctx.fillStyle = '#5c584e';
529:   rr(ctx, cx - T * .3, base - T * .22, T * .6, T * .2, 2); ctx.fill();
530:   ctx.fillStyle = '#6d685c';
531:   rr(ctx, cx - T * .24, base - T * .5, T * .48, T * .29, 2); ctx.fill();
532:   ctx.fillStyle = '#807a6c';
533:   ctx.beginPath();
534:   ctx.arc(cx, base - T * .66, T * .13, 0, TAU); ctx.fill();
535:   ctx.beginPath();
536:   ctx.moveTo(cx - T * .17, base - T * .52); ctx.lineTo(cx - T * .3, base - T * .36); ctx.lineTo(cx - T * .16, base - T * .38);
537:   ctx.lineTo(cx + T * .16, base - T * .38); ctx.lineTo(cx + T * .3, base - T * .36); ctx.lineTo(cx + T * .17, base - T * .52);
538:   ctx.closePath(); ctx.fill();
539:   // ember heart
540:   const pulse = .6 + .4 * Math.sin(now / 700);
541:   ctx.fillStyle = withAlpha(p.accent, .55 * pulse);
542:   ctx.beginPath(); ctx.arc(cx, base - T * .56, T * .04, 0, TAU); ctx.fill();
543:   ctx.strokeStyle = withAlpha(p.accent, .2 * pulse); ctx.lineWidth = 1;
