547: function drawTileObject(ctx, ch, x, y, T, p, now, tx, ty) {
548:   switch (ch) {
549:     case '#': drawTree(ctx, x, y, T, p); break;
550:     case 'T': drawTree(ctx, x, y, T, p, { big: true }); break;
551:     case '^': drawMountain(ctx, x, y, T, p, tx, ty); break;
552:     case 'r': drawRock(ctx, x, y, T, p, tx, ty); break;
553:     case 'R': drawRock(ctx, x, y, T, p, tx, ty); break;
554:     case 'H': case 'h': case 'D': drawHouseTile(ctx, ch, x, y, T, p, tx, ty); break;
555:     case 'W': drawHouseTile(ctx, 'H', x, y, T, p, tx, ty); ctx.fillStyle = 'rgba(10,8,8,.25)'; ctx.fillRect(x, y, T, T); break;
556:     case 'f': drawFence(ctx, x, y, T, p); break;
557:     case 'g': drawGrave(ctx, x, y, T); break;
558:     case 't': drawStump(ctx, x, y, T); break;
559:     case 'B': drawBones(ctx, x, y, T); break;
560:     case 'n': drawTent(ctx, x, y, T, p); break;
561:     case 'L': drawLamp(ctx, x, y, T, now, p); break;
562:     case 'A': drawStatue(ctx, x, y, T, p, now); break;
563:     case 'i': drawSign(ctx, x, y, T, p); break;
564:   }
565: }
