567: // ── particles ─────────────────────────────────────────────────
568: function drawAmbient(ctx, W, H, zone, now, time, T) {
569:   const kind = zone.ambient;
570:   const count = kind === 'citadel' ? 26 : kind === 'mire' ? 30 : 30;
571:   const rng = (i) => hash(i * 13 + 7, i * 29 + 3);
572:   for (let i = 0; i < count; i++) {
573:     const speed = .008 + rng(i) * .016;
574:     const y = ((rng(i + 40) * H) + now * speed * (kind === 'forest' ? .3 : 1)) % H;
575:     let x = (rng(i + 90) * W + Math.sin(now / 2200 + i) * 24) % W;
576:     if (x < 0) x += W;
577:     const a = .25 + .55 * Math.abs(Math.sin(now / 900 + i * 1.7));
578:     if (kind === 'forest') {
579:       const firefly = i % 3 !== 0;
580:       if (firefly) {
581:         ctx.fillStyle = withAlpha('#c8e88a', a * .65);
582:         ctx.beginPath(); ctx.arc(x, y, 1.2 + rng(i) * 1.2, 0, TAU); ctx.fill();
583:       } else {
584:         ctx.fillStyle = withAlpha('#7a6b3a', a * .35);
585:         ctx.beginPath(); ctx.ellipse(x, y, 3, 1.4, now / 2000 + i, 0, TAU); ctx.fill();
586:       }
587:     } else if (kind === 'plains') {
588:       ctx.fillStyle = withAlpha('#e8d39a', a * .3);
589:       ctx.beginPath(); ctx.arc(x, y, 1 + rng(i), 0, TAU); ctx.fill();
590:     } else if (kind === 'mire') {
591:       ctx.fillStyle = withAlpha(i % 2 ? '#a8e6d0' : '#d8e8c0', a * .35);
592:       ctx.beginPath(); ctx.arc(x, y, 1 + rng(i) * 1.6, 0, TAU); ctx.fill();
593:     } else if (kind === 'peaks' || kind === 'village') {
594:       const size = 1 + rng(i) * 1.6;
595:       ctx.fillStyle = withAlpha(i % 3 ? '#f0a15a' : '#ffd29a', a * .7);
596:       ctx.beginPath(); ctx.arc(x, y, size, 0, TAU); ctx.fill();
597:       if (i % 7 === 0) {
598:         ctx.fillStyle = withAlpha('#ffd29a', a * .18);
599:         ctx.beginPath(); ctx.arc(x, y, size * 4, 0, TAU); ctx.fill();
600:       }
601:     } else {
602:       ctx.fillStyle = withAlpha('#b9a8d8', a * .3);
603:       ctx.beginPath(); ctx.arc(x, y, 1 + rng(i) * 1.4, 0, TAU); ctx.fill();
604:     }
605:   }
606: }
