608: // ── lighting ──────────────────────────────────────────────────
609: let lightCanvas = null;
610: function getLightCanvas(W, H) {
611:   if (!lightCanvas) lightCanvas = document.createElement('canvas');
612:   if (lightCanvas.width !== W || lightCanvas.height !== H) { lightCanvas.width = W; lightCanvas.height = H; }
613:   return lightCanvas;
614: }
615: 
616: function drawTimeOverlay(ctx, W, H, now, zone, lights) {
617:   const cycle = state.time; // 0 midnight, .5 noon
618:   const brightness = .5 - .5 * Math.cos(cycle * TAU);
619:   let night = 1 - brightness;
620:   if (zone.ambient === 'citadel') night = Math.max(night, .55);
621:   if (zone.ambient === 'mire') night = Math.max(night, .3);
622:   // warm dusk
623:   if (brightness > .12 && brightness < .75) {
624:     const dusk = 1 - Math.abs(brightness - .35) / .4;
625:     if (dusk > 0) {
626:       ctx.fillStyle = withAlpha('#d2763a', Math.max(0, dusk) * .1);
627:       ctx.fillRect(0, 0, W, H);
628:     }
629:   }
630:   if (night > .04) {
631:     const lc = getLightCanvas(W, H);
632:     const lc2 = lc.getContext('2d');
633:     lc2.clearRect(0, 0, W, H);
634:     lc2.fillStyle = withAlpha('#050a18', Math.min(.72, night * .68));
635:     lc2.fillRect(0, 0, W, H);
636:     lc2.globalCompositeOperation = 'destination-out';
637:     for (const l of lights) {
638:       const r = l.r * (1 + Math.sin(now / 700 + l.x) * .03);
639:       const g = lc2.createRadialGradient(l.x, l.y, 0, l.x, l.y, r);
640:       g.addColorStop(0, `rgba(0,0,0,${l.strength || .95})`);
641:       g.addColorStop(.6, `rgba(0,0,0,${(l.strength || .95) * .35})`);
642:       g.addColorStop(1, 'rgba(0,0,0,0)');
643:       lc2.fillStyle = g;
644:       lc2.beginPath(); lc2.arc(l.x, l.y, r, 0, TAU); lc2.fill();
645:     }
646:     lc2.globalCompositeOperation = 'source-over';
647:     ctx.drawImage(lc, 0, 0);
648:     // warm glow pass
649:     ctx.save();
650:     ctx.globalCompositeOperation = 'lighter';
651:     for (const l of lights) {
652:       if (!l.glow) continue;
653:       const g = ctx.createRadialGradient(l.x, l.y, 0, l.x, l.y, l.r * .8);
654:       g.addColorStop(0, withAlpha(l.glow, .2 * night));
655:       g.addColorStop(1, withAlpha(l.glow, 0));
656:       ctx.fillStyle = g;
657:       ctx.beginPath(); ctx.arc(l.x, l.y, l.r * .8, 0, TAU); ctx.fill();
658:     }
659:     ctx.restore();
660:   }
661: }
