663: // ── main world renderer ───────────────────────────────────────
664: export function renderWorld(ctx, W, H, view) {
665:   const { zone, tile: T, camx, camy, player, now } = view;
666:   const p = P[zone.ambient] || P.village;
667:   const map = zone.map;
668:   ctx.clearRect(0, 0, W, H);
669:   ctx.fillStyle = '#070a10';
670:   ctx.fillRect(0, 0, W, H);
671:   const x0 = Math.max(0, Math.floor(camx / T) - 1);
672:   const y0 = Math.max(0, Math.floor(camy / T) - 1);
673:   const x1 = Math.min(map.w - 1, Math.ceil((camx + W) / T) + 1);
674:   const y1 = Math.min(map.h - 1, Math.ceil((camy + H) / T) + 1);
675:   const sx = (tx) => tx * T - camx;
676:   const sy = (ty) => ty * T - camy;
677: 
678:   for (let ty = y0; ty <= y1; ty++) {
679:     for (let tx = x0; tx <= x1; tx++) {
680:       const ch = map.g[ty][tx];
681:       drawGround(ctx, ch, sx(tx), sy(ty), T, p, now, tx, ty);
682:     }
683:   }
684:   // fog / haze bands
685:   if (zone.ambient === 'mire') {
686:     for (let i = 0; i < 4; i++) {
687:       const fy = H * (.2 + i * .2) + Math.sin(now / 5000 + i) * 20;
688:       const g = ctx.createLinearGradient(0, fy - 50, 0, fy + 50);
689:       g.addColorStop(0, 'rgba(170,210,200,0)');
690:       g.addColorStop(.5, 'rgba(170,210,200,.035)');
691:       g.addColorStop(1, 'rgba(170,210,200,0)');
692:       ctx.fillStyle = g; ctx.fillRect(0, fy - 50, W, 100);
693:     }
694:   }
695: 
696:   // collect drawables
697:   const drawables = [];
698:   const lights = [];
699:   for (let ty = y0; ty <= y1; ty++) {
700:     for (let tx = x0; tx <= x1; tx++) {
701:       const ch = map.g[ty][tx];
702:       if (BLOCKED_OBJECTS.has(ch)) {
703:         drawables.push({ y: (ty + 1) * T, draw: () => drawTileObject(ctx, ch, sx(tx), sy(ty), T, p, now, tx, ty) });
704:         if (ch === 'L') lights.push({ x: sx(tx) + T * .5, y: sy(ty) + T * .3, r: T * 2.1, glow: '#ffc27a' });
705:       }
706:     }
