185:   const type = def.shape || 'human';
186:   const col = def.color || '#8a6a4a';
187:   const acc = def.accent || '#f0a15a';
188:   const bob = Math.sin(t * 2.1 + (def.seed || 0)) * s * .018 + (fx.bob || 0);
189:   const scale = def.size || 1;
190:   const H = s * 1.5 * scale;
191:   const foot = y + bob;
192:   const shake = fx.shake || 0;
193:   const alpha = fx.alpha ?? 1;
194:   const flash = fx.flash || 0;
195:   ctx.save();
196:   ctx.translate(x + shake, 0);
197:   ctx.globalAlpha = alpha;
198:   // shadow
199:   ctx.fillStyle = 'rgba(0,0,0,.36)';
200:   ctx.beginPath(); ctx.ellipse(0, foot, H * .34, H * .075, 0, 0, TAU); ctx.fill();
201: 
202:   const body = (c = col) => {
203:     if (flash > 0) return '#fff4e8';
204:     return c;
205:   };
206:   ctx.shadowColor = withAlpha(acc, .35);
207:   ctx.shadowBlur = s * .12;
208: 
209:   if (type === 'wisp') {
210:     const fy = foot - H * .55;
211:     ctx.shadowBlur = s * .3;
212:     const g = ctx.createRadialGradient(0, fy, 0, 0, fy, H * .34);
213:     g.addColorStop(0, '#fff1cf'); g.addColorStop(.35, acc); g.addColorStop(1, 'rgba(0,0,0,0)');
214:     ctx.fillStyle = g;
215:     ctx.beginPath(); ctx.arc(0, fy, H * .32, 0, TAU); ctx.fill();
216:     ctx.fillStyle = body(col);
217:     ctx.beginPath(); ctx.arc(0, fy, H * .15, 0, TAU); ctx.fill();
218:     // trailing wisps
219:     ctx.strokeStyle = withAlpha(acc, .55); ctx.lineWidth = s * .035;
220:     for (let i = 0; i < 3; i++) {
221:       ctx.beginPath();
222:       ctx.moveTo((i - 1) * s * .12, fy + H * .1);
223:       ctx.quadraticCurveTo((i - 1) * s * .22, fy + H * .26, (i - 1) * s * .12 + Math.sin(t + i) * s * .06, fy + H * .38);
224:       ctx.stroke();
225:     }
226:     ctx.fillStyle = '#2b1810';
227:     ctx.beginPath(); ctx.arc(-H * .05, fy - H * .02, s * .022, 0, TAU); ctx.fill();
228:     ctx.beginPath(); ctx.arc(H * .06, fy - H * .02, s * .022, 0, TAU); ctx.fill();
229:   } else if (type === 'wolf') {
230:     const bodyY = foot - H * .34;
231:     ctx.fillStyle = body(col);
232:     ctx.beginPath(); ctx.ellipse(0, bodyY, H * .34, H * .18, -.1, 0, TAU); ctx.fill();
233:     // legs
234:     ctx.strokeStyle = shade(col, -30); ctx.lineWidth = s * .075; ctx.lineCap = 'round';
235:     for (const [ox, oy] of [[-.17, .14], [.16, .13], [-.06, .18], [.26, .18]]) {
236:       ctx.beginPath(); ctx.moveTo(ox * H, bodyY + H * .1); ctx.lineTo(ox * H + oy * H * .8, foot); ctx.stroke();
237:     }
238:     // head
239:     ctx.fillStyle = body(shade(col, 12));
240:     ctx.beginPath(); ctx.ellipse(-H * .3, bodyY - H * .12, H * .17, H * .14, -.3, 0, TAU); ctx.fill();
241:     ctx.beginPath(); ctx.moveTo(-H * .44, bodyY - H * .17); ctx.lineTo(-H * .56, bodyY - H * .2); ctx.lineTo(-H * .45, bodyY - H * .05); ctx.fill();
242:     // ears
243:     ctx.fillStyle = shade(col, -20);
244:     ctx.beginPath(); ctx.moveTo(-H * .3, bodyY - H * .24); ctx.lineTo(-H * .26, bodyY - H * .38); ctx.lineTo(-H * .19, bodyY - H * .25); ctx.fill();
245:     ctx.beginPath(); ctx.moveTo(-H * .4, bodyY - H * .22); ctx.lineTo(-H * .4, bodyY - H * .36); ctx.lineTo(-H * .32, bodyY - H * .24); ctx.fill();
246:     // tail
247:     ctx.strokeStyle = shade(col, -15); ctx.lineWidth = s * .06;
248:     ctx.beginPath(); ctx.moveTo(H * .3, bodyY - H * .08); ctx.quadraticCurveTo(H * .48, bodyY - H * .2, H * .42, bodyY - H * .34); ctx.stroke();
249:     // eyes
250:     ctx.fillStyle = acc; ctx.shadowColor = acc; ctx.shadowBlur = s * .1;
251:     ctx.beginPath(); ctx.arc(-H * .4, bodyY - H * .13, s * .022, 0, TAU); ctx.fill();
252:     // ember embers
253:     if (acc) {
254:       ctx.globalAlpha = alpha * .7;
255:       for (let i = 0; i < 3; i++) {
256:         const p = (t * .5 + i * .33) % 1;
257:         ctx.fillStyle = withAlpha(acc, 1 - p);
258:         ctx.beginPath(); ctx.arc(.15 * H + Math.sin(t + i) * 8, bodyY - H * .15 - p * H * .4, s * .014, 0, TAU); ctx.fill();
259:       }
260:       ctx.globalAlpha = alpha;
261:     }
262:   } else if (type === 'husk' || type === 'human') {
263:     const h = H * .78;
264:     const wide = type === 'husk' ? .4 : .34;
265:     // body
266:     ctx.fillStyle = body(col);
267:     rr(ctx, -H * wide * .6, foot - h, H * wide * 1.2, h * .72, s * .06); ctx.fill();
268:     // legs
269:     ctx.fillStyle = shade(col, -35);
270:     rr(ctx, -H * .16, foot - h * .35, H * .13, h * .35, 2); ctx.fill();
271:     rr(ctx, H * .03, foot - h * .35, H * .13, h * .35, 2); ctx.fill();
272:     // arms
273:     ctx.strokeStyle = shade(col, 8); ctx.lineWidth = s * .085; ctx.lineCap = 'round';
274:     ctx.beginPath(); ctx.moveTo(-H * wide * .55, foot - h * .85); ctx.lineTo(-H * wide * .8, foot - h * .45); ctx.stroke();
275:     ctx.beginPath(); ctx.moveTo(H * wide * .55, foot - h * .85); ctx.lineTo(H * wide * .75, foot - h * .5); ctx.stroke();
276:     // head
277:     ctx.fillStyle = type === 'husk' ? '#c6b89c' : PALETTES[(def.seed || 0) % 6].skin;
278:     ctx.beginPath(); ctx.arc(0, foot - h - s * .04, H * .115, 0, TAU); ctx.fill();
279:     ctx.fillStyle = '#2b211c';
280:     if (type === 'husk') {
281:       ctx.beginPath(); ctx.arc(-H * .04, foot - h - s * .04, s * .025, 0, TAU); ctx.fill();
282:       ctx.beginPath(); ctx.arc(H * .04, foot - h - s * .04, s * .025, 0, TAU); ctx.fill();
283:       ctx.fillStyle = withAlpha(acc, .8);
284:       rr(ctx, -H * .1, foot - h * .72, H * .2, s * .03, 2); ctx.fill();
285:     } else {
286:       // hood
287:       ctx.fillStyle = shade(col, -35);
288:       ctx.beginPath(); ctx.arc(0, foot - h - s * .03, H * .14, Math.PI * 1.02, Math.PI * 1.98); ctx.fill();
289:       ctx.fillStyle = acc;
290:       ctx.beginPath(); ctx.arc(-H * .04, foot - h, s * .018, 0, TAU); ctx.fill();
291:       ctx.beginPath(); ctx.arc(H * .04, foot - h, s * .018, 0, TAU); ctx.fill();
292:       // weapon
293:       ctx.strokeStyle = '#cfc6b2'; ctx.lineWidth = s * .04;
294:       ctx.beginPath(); ctx.moveTo(-H * .3, foot - h * .7); ctx.lineTo(-H * .52, foot - h * .15); ctx.stroke();
295:     }
296:     // belt / accent
297:     ctx.fillStyle = withAlpha(acc, .8);
298:     rr(ctx, -H * wide * .55, foot - h * .42, H * wide * 1.1, s * .035, 2); ctx.fill();
299:   } else if (type === 'plant') {
300:     const baseY = foot;
301:     ctx.fillStyle = body(shade(col, -18));
302:     ctx.beginPath(); ctx.moveTo(-H * .25, baseY); ctx.quadraticCurveTo(-H * .36, baseY - H * .7, 0, baseY - H * .85); ctx.quadraticCurveTo(H * .36, baseY - H * .7, H * .25, baseY); ctx.closePath(); ctx.fill();
303:     // petals / maw
304:     ctx.fillStyle = body(col);
305:     for (let i = 0; i < 7; i++) {
306:       const a = -Math.PI + i * Math.PI / 6;
307:       ctx.beginPath();
308:       ctx.ellipse(Math.cos(a) * H * .17, baseY - H * .78 + Math.sin(a) * H * .08, H * .12, H * .055, a, 0, TAU);
309:       ctx.fill();
310:     }
311:     ctx.fillStyle = '#1d2a18';
312:     ctx.beginPath(); ctx.arc(0, baseY - H * .78, H * .11, 0, TAU); ctx.fill();
313:     ctx.fillStyle = acc;
314:     for (let i = 0; i < 5; i++) {
315:       const a = i / 5 * TAU + t * .2;
316:       ctx.beginPath(); ctx.arc(Math.cos(a) * H * .07, baseY - H * .78 + Math.sin(a) * H * .05, s * .016, 0, TAU); ctx.fill();
317:     }
318:     // vines
319:     ctx.strokeStyle = withAlpha(shade(col, 20), .8); ctx.lineWidth = s * .045;
320:     for (let i = 0; i < 3; i++) {
321:       ctx.beginPath();
322:       ctx.moveTo(-H * .2 + i * H * .2, baseY - H * .1);
323:       ctx.quadraticCurveTo(-H * .4 + i * H * .34, baseY - H * .25, -H * .44 + i * H * .3, baseY - H * .45);
324:       ctx.stroke();
325:     }
326:   } else if (type === 'toad') {
327:     const h = H * .5;
328:     ctx.fillStyle = body(col);
329:     ctx.beginPath(); ctx.ellipse(0, foot - h * .42, H * .38, h * .7, 0, 0, TAU); ctx.fill();
330:     ctx.beginPath(); ctx.ellipse(-H * .2, foot - h * .7, H * .16, h * .34, -.2, 0, TAU); ctx.fill();
331:     ctx.fillStyle = shade(col, 25);
332:     ctx.beginPath(); ctx.arc(-H * .27, foot - h * .95, H * .09, 0, TAU); ctx.fill();
333:     ctx.beginPath(); ctx.arc(-H * .07, foot - h * .95, H * .09, 0, TAU); ctx.fill();
334:     ctx.fillStyle = '#10170f';
335:     ctx.beginPath(); ctx.arc(-H * .29, foot - h * .95, s * .04, 0, TAU); ctx.fill();
336:     ctx.beginPath(); ctx.arc(-H * .05, foot - h * .95, s * .04, 0, TAU); ctx.fill();
337:     ctx.strokeStyle = '#1d2a18'; ctx.lineWidth = s * .03;
338:     ctx.beginPath(); ctx.arc(-H * .17, foot - h * .78, H * .16, .2, Math.PI - .2); ctx.stroke();
339:     // spots
340:     ctx.fillStyle = withAlpha(acc, .5);
341:     for (let i = 0; i < 4; i++) {
342:       ctx.beginPath(); ctx.arc(-H * .1 + i * H * .09, foot - h * .45 + (i % 2) * H * .1, s * .035, 0, TAU); ctx.fill();
343:     }
344:   } else if (type === 'wraith' || type === 'witch') {
345:     const h = H * .8;
346:     const float = Math.sin(t * 1.4) * s * .04;
347:     ctx.fillStyle = body(col);
348:     ctx.globalAlpha = alpha * .9;
349:     ctx.beginPath();
350:     ctx.moveTo(-H * .32, foot - h * .15 + float);
351:     ctx.quadraticCurveTo(-H * .42, foot - h * .75 + float, 0, foot - h + float);
352:     ctx.quadraticCurveTo(H * .42, foot - h * .75 + float, H * .32, foot - h * .15 + float);
353:     ctx.lineTo(H * .24, foot - h * .02 + float);
354:     ctx.lineTo(H * .12, foot - h * .14 + float);
355:     ctx.lineTo(0, foot + float);
356:     ctx.lineTo(-H * .16, foot - h * .14 + float);
357:     ctx.lineTo(-H * .26, foot - h * .02 + float);
358:     ctx.closePath(); ctx.fill();
359:     ctx.globalAlpha = alpha;
360:     // hood / face void
361:     ctx.fillStyle = '#171420';
362:     ctx.beginPath(); ctx.ellipse(-H * .02, foot - h * .78 + float, H * .14, H * .16, 0, 0, TAU); ctx.fill();
363:     ctx.fillStyle = acc; ctx.shadowColor = acc; ctx.shadowBlur = s * .16;
364:     if (type === 'witch') {
365:       ctx.beginPath(); ctx.ellipse(-H * .07, foot - h * .77 + float, s * .028, s * .018, 0, 0, TAU); ctx.fill();
366:       ctx.beginPath(); ctx.ellipse(H * .05, foot - h * .77 + float, s * .028, s * .018, 0, 0, TAU); ctx.fill();
367:       // hat
368:       ctx.fillStyle = body(shade(col, -18));
369:       ctx.beginPath(); ctx.moveTo(-H * .24, foot - h * .85 + float); ctx.lineTo(-H * .02, foot - h * 1.22 + float); ctx.lineTo(H * .18, foot - h * .85 + float); ctx.closePath(); ctx.fill();
370:       ctx.beginPath(); ctx.ellipse(-H * .03, foot - h * .86 + float, H * .28, H * .04, 0, 0, TAU); ctx.fill();
371:       // staff
372:       ctx.strokeStyle = '#6b5238'; ctx.lineWidth = s * .035;
373:       ctx.beginPath(); ctx.moveTo(-H * .42, foot + float); ctx.lineTo(-H * .48, foot - h + float); ctx.stroke();
374:       ctx.fillStyle = acc; ctx.shadowBlur = s * .2;
375:       ctx.beginPath(); ctx.arc(-H * .48, foot - h + float, s * .05, 0, TAU); ctx.fill();
376:     } else {
377:       ctx.beginPath(); ctx.arc(-H * .05, foot - h * .79 + float, s * .022, 0, TAU); ctx.fill();
378:       ctx.beginPath(); ctx.arc(H * .03, foot - h * .79 + float, s * .022, 0, TAU); ctx.fill();
379:     }
380:     // wisps
381:     ctx.globalAlpha = alpha * .5;
382:     ctx.fillStyle = acc;
383:     for (let i = 0; i < 4; i++) {
384:       const a = t * .8 + i * 1.6;
385:       ctx.beginPath(); ctx.arc(Math.cos(a) * H * .28, foot - h * .5 + Math.sin(a * 1.3) * H * .2, s * .012, 0, TAU); ctx.fill();
386:     }
387:   } else if (type === 'golem') {
388:     const h = H * .8;
389:     ctx.fillStyle = body(col);
390:     rr(ctx, -H * .3, foot - h, H * .6, h, s * .06); ctx.fill();
391:     ctx.fillStyle = shade(col, -18);
392:     rr(ctx, -H * .42, foot - h * .92, H * .18, h * .5, s * .04); ctx.fill();
393:     rr(ctx, H * .24, foot - h * .92, H * .18, h * .5, s * .04); ctx.fill();
394:     rr(ctx, -H * .2, foot - h * .36, H * .16, h * .36, 2); ctx.fill();
395:     rr(ctx, H * .05, foot - h * .36, H * .16, h * .36, 2); ctx.fill();
396:     // head
397:     ctx.fillStyle = shade(col, 10);
398:     rr(ctx, -H * .16, foot - h - H * .1, H * .32, H * .16, s * .03); ctx.fill();
399:     // glowing cracks
400:     ctx.strokeStyle = acc; ctx.lineWidth = s * .03; ctx.shadowColor = acc; ctx.shadowBlur = s * .15;
401:     ctx.beginPath();
402:     ctx.moveTo(-H * .2, foot - h * .9); ctx.lineTo(-H * .06, foot - h * .7); ctx.lineTo(-H * .14, foot - h * .5); ctx.lineTo(H * .04, foot - h * .28);
403:     ctx.stroke();
404:     ctx.beginPath(); ctx.moveTo(H * .16, foot - h * .82); ctx.lineTo(H * .08, foot - h * .62); ctx.stroke();
405:     ctx.fillStyle = acc;
406:     ctx.beginPath(); ctx.arc(-H * .07, foot - h - H * .02, s * .022, 0, TAU); ctx.fill();
407:     ctx.beginPath(); ctx.arc(H * .07, foot - h - H * .02, s * .022, 0, TAU); ctx.fill();
408:   } else if (type === 'knight' || type === 'king') {
409:     const h = H * .82 * (type === 'king' ? 1.12 : 1);
410:     const wide = type === 'king' ? .42 : .36;
411:     // cape
412:     ctx.fillStyle = withAlpha(shade(col, -35), .9);
413:     ctx.beginPath();
414:     ctx.moveTo(-H * wide * .55, foot - h * .9);
415:     ctx.lineTo(-H * wide * 1.05, foot - h * .02);
416:     ctx.lineTo(H * wide * .2, foot - h * .06);
417:     ctx.closePath(); ctx.fill();
418:     // body armour
419:     ctx.fillStyle = body(col);
420:     rr(ctx, -H * wide * .62, foot - h, H * wide * 1.24, h * .7, s * .05); ctx.fill();
421:     ctx.fillStyle = shade(col, 18);
422:     ctx.beginPath(); ctx.moveTo(-H * wide * .62, foot - h + s * .02); ctx.lineTo(0, foot - h * .78); ctx.lineTo(H * wide * .62, foot - h + s * .02); ctx.fill();
423:     // legs
424:     ctx.fillStyle = shade(col, -25);
425:     rr(ctx, -H * .17, foot - h * .34, H * .14, h * .34, 2); ctx.fill();
426:     rr(ctx, H * .03, foot - h * .34, H * .14, h * .34, 2); ctx.fill();
427:     // arms
428:     ctx.fillStyle = shade(col, 6);
429:     rr(ctx, -H * wide * .8, foot - h * .8, H * .16, h * .38, s * .03); ctx.fill();
430:     // helm
431:     ctx.fillStyle = shade(col, 25);
432:     ctx.beginPath(); ctx.arc(0, foot - h - s * .03, H * .13, Math.PI, TAU); ctx.fill();
433:     rr(ctx, -H * .13, foot - h - s * .04, H * .26, H * .13, s * .02); ctx.fill();
434:     ctx.fillStyle = '#1a120e';
435:     rr(ctx, -H * .09, foot - h + H * .02, H * .18, s * .022, 1); ctx.fill();
436:     ctx.fillStyle = acc; ctx.shadowColor = acc; ctx.shadowBlur = s * .14;
437:     ctx.beginPath(); ctx.arc(-H * .05, foot - h + H * .035, s * .015, 0, TAU); ctx.fill();
438:     ctx.beginPath(); ctx.arc(H * .05, foot - h + H * .035, s * .015, 0, TAU); ctx.fill();
439:     // weapon
440:     ctx.strokeStyle = '#cfd6da'; ctx.lineWidth = s * .055;
441:     ctx.beginPath(); ctx.moveTo(-H * wide * .8, foot - h * .38); ctx.lineTo(-H * wide * .8 - H * .18, foot + s * .06); ctx.stroke();
442:     ctx.fillStyle = withAlpha(acc, .85);
443:     ctx.beginPath(); ctx.arc(-H * wide * .8, foot - h * .84, s * .03, 0, TAU); ctx.fill();
444:     if (type === 'king') {
445:       // crown
446:       ctx.fillStyle = acc; ctx.shadowColor = acc; ctx.shadowBlur = s * .2;
447:       const cy = foot - h - H * .16;
448:       ctx.beginPath();
449:       ctx.moveTo(-H * .14, cy); ctx.lineTo(-H * .12, cy - H * .08); ctx.lineTo(-H * .06, cy - H * .03);
450:       ctx.lineTo(0, cy - H * .11); ctx.lineTo(H * .06, cy - H * .03); ctx.lineTo(H * .12, cy - H * .08); ctx.lineTo(H * .14, cy);
451:       ctx.closePath(); ctx.fill();
452:       // flame aura
453:       ctx.globalAlpha = alpha * .35;
454:       for (let i = 0; i < 6; i++) {
455:         const a = t * 1.2 + i;
456:         ctx.fillStyle = withAlpha(acc, .5 + .3 * Math.sin(a));
457:         ctx.beginPath();
458:         ctx.ellipse(Math.cos(a) * H * .36, foot - h * .55 + Math.sin(a * 1.7) * H * .26, s * .05, s * .11, Math.sin(a), 0, TAU);
459:         ctx.fill();
460:       }
461:       ctx.globalAlpha = alpha;
462:     }
463:   } else {
464:     ctx.fillStyle = body(col);
465:     ctx.beginPath(); ctx.arc(0, foot - H * .4, H * .28, 0, TAU); ctx.fill();
466:   }
467:   ctx.restore();
468: }
