470: // ── portraits ─────────────────────────────────────────────────
471: export function drawPortrait(canvas, member, opts = {}) {
472:   const ctx = canvas.getContext('2d');
473:   const w = canvas.width, h = canvas.height;
474:   const dpr = opts.dpr || 1;
475:   ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
476:   const W = w / dpr, H = h / dpr;
477:   const pal = paletteFor(member);
478:   const cls = CLASSES[member.classId];
479:   const accent = cls?.color || pal.accent;
480:   ctx.clearRect(0, 0, W, H);
481:   const bg = ctx.createLinearGradient(0, 0, W, H);
482:   bg.addColorStop(0, shade(pal.cloth, 22));
483:   bg.addColorStop(.55, '#151b26');
484:   bg.addColorStop(1, '#0a0e15');
485:   ctx.fillStyle = bg; ctx.fillRect(0, 0, W, H);
486:   // halo
487:   const halo = ctx.createRadialGradient(W * .5, H * .38, 0, W * .5, H * .38, W * .55);
488:   halo.addColorStop(0, withAlpha(accent, .24));
489:   halo.addColorStop(1, 'rgba(0,0,0,0)');
490:   ctx.fillStyle = halo; ctx.fillRect(0, 0, W, H);
491:   // sigil watermark
492:   ctx.save();
493:   ctx.translate(W * .5, H * .48); ctx.rotate(-.12);
494:   ctx.font = `${W * .85}px Georgia, serif`;
495:   ctx.fillStyle = withAlpha(accent, .07);
496:   ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
497:   ctx.fillText(cls?.sigil || '✦', 0, W * .05);
498:   ctx.restore();
499:   // bust
500:   const cx = W * .5, shoulder = H * .95;
501:   ctx.fillStyle = shade(pal.cloth, -20);
502:   ctx.beginPath();
503:   ctx.moveTo(cx - W * .4, shoulder);
504:   ctx.quadraticCurveTo(cx - W * .3, H * .62, cx - W * .14, H * .58);
505:   ctx.lineTo(cx + W * .14, H * .58);
506:   ctx.quadraticCurveTo(cx + W * .3, H * .62, cx + W * .4, shoulder);
507:   ctx.closePath(); ctx.fill();
508:   // collar
509:   ctx.strokeStyle = withAlpha(accent, .7); ctx.lineWidth = W * .012;
510:   ctx.beginPath(); ctx.moveTo(cx - W * .13, H * .6); ctx.lineTo(cx, H * .72); ctx.lineTo(cx + W * .13, H * .6); ctx.stroke();
511:   // neck
512:   ctx.fillStyle = shade(pal.skin, -18);
513:   ctx.fillRect(cx - W * .07, H * .48, W * .14, H * .15);
514:   // head
515:   const headR = W * .19;
516:   const hy = H * .37;
517:   ctx.fillStyle = pal.skin;
518:   ctx.beginPath(); ctx.ellipse(cx, hy, headR * .84, headR, 0, 0, TAU); ctx.fill();
519:   // hair
520:   ctx.fillStyle = pal.hair;
