78: export async function runStory(story, ctx = {}) {
79:   if (!story) return { done: true };
80:   let gen;
81:   try {
82:     gen = typeof story === 'function' ? story(ctx) : story;
83:   } catch (err) {
84:     console.error('Story begin error', err);
85:     throw err;
86:   }
87:   if (!gen || typeof gen.next !== 'function') return { done: true };
88:   let step = gen.next();
89:   while (!step.done) {
90:     const result = await exec(step.value, ctx);
91:     if (result && result.__abort) return { aborted: true, result };
92:     step = gen.next(result);
93:   }
94:   return { done: true, value: step.value };
95: }
