// ── Pixel-art characters, portraits & enemies ────────────────────────────
// 16×24 logical-pixel sprites, four directions, idle + two-step walk.
// Drawn with crisp pixel primitives; blitted unsmoothed in the render loop.
import { PAL, CHAR_PALS, px, pr, lineV, lineH, spriteCanvas } from './pixel.js';
import { CLASSES, PALETTES } from '../data/classes.js';

export const TAU = Math.PI * 2;
export const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
export const lerp = (a, b, t) => a + (b - a) * t;
export const hash = (x, y) => {
  let n = (x * 374761393 + y * 668265263) | 0;
  n = (n ^ (n >> 13)) * 1274126177;
  return ((n ^ (n >> 16)) >>> 0) / 4294967295;
};
export function rr(ctx, x, y, w, h, r) {
  r = Math.min(r, Math.abs(w) / 2, Math.abs(h) / 2);
  ctx.beginPath();
  ctx.moveTo(x + r, y);
  ctx.arcTo(x + w, y, x + w, y + h, r);
  ctx.arcTo(x + w, y + h, x, y + h, r);
  ctx.arcTo(x, y + h, x, y, r);
  ctx.arcTo(x, x + w, y, r);
  ctx.closePath();
}
export function shade(hex, amt) {
  if (!hex || hex[0] !== '#') return hex;
  const n = parseInt(hex.slice(1), 16);
  const r = clamp(((n >> 16) & 255) + amt, 0, 255);
  const g = clamp(((n >> 8) & 255) + amt, 0, 255);
  const b = clamp((n & 255) + amt, 0, 255);
  return `rgb(${r | 0},${g | 0},${b | 0})`;
}
export function withAlpha(hex, a) {
  if (!hex || hex[0] !== '#') return hex;
  const n = parseInt(hex.slice(1), 16);
  return `rgba(${(n >> 16) & 255},${(n >> 8) & 255},${n & 255},${a})`;
}
export const CLASS_COLORS = {
  vanguard: '#e2a15f', emberweaver: '#f0774d', shadowblade: '#a58ae0',
  warden: '#79c98b', stormcaller: '#76b8ec', ronin: '#e07a6b',
};
export function paletteFor(member) {
  if (!member) return PALETTES[0];
  const base = PALETTES[member.palette ?? 0] || PALETTES[0];
  const cls = CLASSES[member.classId];
  return { ...base, accent: cls?.color || base.accent };
}

// ── 16×24 pixel sprite ───────────────────────────────────────────────────
// (cx, cy) = feet centre. Natural height 24px, scaled by opt.scale.
const BODY = 9;   // tunic height
const LEGS = 5;   // leg length
const BOOT = 2;
const HEAD = 6;

function shadeC(c, amt) { return shade(c, amt); }

// head facing down: face + hair cap
function headDown(ctx, cx, hy, pal, style) {
  // face
  pr(ctx, cx - 3, hy, HEAD, HEAD, pal.skin);
  lineV(ctx, cx - 2, hy + 1, 2, '#1a1410'); // nose bridge hint
  // eyes
  px(ctx, cx - 2, hy + 2, '#241a18');
  px(ctx, cx + 1, hy + 2, '#241a18');
  px(ctx, cx - 2, hy + 3, '#241a18');
  px(ctx, cx + 1, hy + 3, '#241a18');
  // mouth
  px(ctx, cx, hy + 4, '#7a4a40');
  // hair cap
  const hair = pal.hair;
  if (style.hair === 'long') {
    lineH(ctx, cx - 4, hy - 2, 8, hair);
    lineH(ctx, cx - 4, hy - 1, 4, hair);
    lineH(ctx, cx, hy - 1, 4, hair);
    lineH(ctx, cx - 3, hy, 2, hair);
    lineH(ctx, cx + 1, hy, 2, hair);
    // back hair flows down shoulders
    lineV(ctx, cx - 5, hy + 1, 4, shadeC(hair, -20));
    lineV(ctx, cx + 4, hy + 1, 4, shadeC(hair, -20));
  } else if (style.hair === 'cap') {
    lineH(ctx, cx - 4, hy - 3, 8, hair);
    lineH(ctx, cx - 3, hy - 2, 6, hair);
    lineH(ctx, cx - 2, hy - 1, 4, hair);
    lineV(ctx, cx - 5, hy, 2, hair);
    lineV(ctx, cx + 4, hy, 2, hair);
  } else {
    // short: sides + top fringe
    lineH(ctx, cx - 4, hy - 2, 2, hair);
    lineH(ctx, cx + 2, hy - 2, 2, hair);
    lineH(ctx, cx - 3, hy - 1, 6, hair);
    lineV(ctx, cx - 4, hy, 2, hair);
    lineV(ctx, cx + 3, hy, 2, hair);
  }
}

function headUp(ctx, cx, hy, pal, style) {
  // back of head
  pr(ctx, cx - 3, hy - 1, HEAD, HEAD, shadeC(pal.skin, -15));
  const hair = pal.hair;
  if (style.hair === 'long') {
    lineH(ctx, cx - 4, hy + 4, 8, hair);
    lineH(ctx, cx - 4, hy + 3, 8, hair);
    lineH(ctx, cx - 4, hy + 2, 6, hair);
    lineV(ctx, cx - 4, hy - 2, 4, hair);
    lineV(ctx, cx + 3, hy - 2, 4, hair);
  } else if (style.hair === 'cap') {
    lineH(ctx, cx - 4, hy + 3, 8, hair);
    lineH(ctx, cx - 3, hy + 2, 6, hair);
    lineH(ctx, cx - 2, hy + 1, 4, hair);
  } else {
    lineH(ctx, cx - 4, hy + 3, 4, hair);
    lineH(ctx, cx, hy + 3, 4, hair);
    lineV(ctx, cx - 4, hy - 1, 2, hair);
    lineV(ctx, cx + 3, hy - 1, 2, hair);
  }
}

// side profile head
function headSide(ctx, cx, cy, dir, pal, style) {
  const h = dir > 0 ? 1 : -1;
  const ox = cx + h * 2;
  pr(ctx, ox - h * 2, cy - 2, 5, 4, pal.skin);
  px(ctx, ox + h, cy - 1, '#241a18');
  px(ctx, ox + h, cy, '#241a18');
  px(ctx, ox + h * 2, cy + 1, '#7a4a40');
  const hair = pal.hair;
  if (style.hair === 'long') {
    lineV(ctx, cx - h * 4, cy - 3, 6, hair);
    lineH(ctx, cx - h * 3, cy - 4, 3 * h > 0 ? 3 : -3, hair);
    lineH(ctx, cx - h * 3, cy + 2, 4 * h > 0 ? 4 : -4, hair);
  } else {
    lineV(ctx, cx - h * 3, cy - 3, 5, hair);
    lineH(ctx, cx - h * 2, cy - 4, 2 * h, hair);
  }
  if (style.hat === 'helm') {
    lineH(ctx, cx - h * 3, cy - 5, 5 * h, '#4a443a');
    pr(ctx, cx - h * 3, cy - 4, 5 * h > 0 ? 5 : -5, 1, '#8a8474');
  }
  if (style.hat === 'veil') {
    lineH(ctx, cx - h * 4, cy - 4, 6 * h, '#5a4a6a');
  }
}

function bodyDown(ctx, cx, by, pal, style) {
  const cloth = pal.cloth;
  // tunic
  pr(ctx, cx - 5, by, 10, BODY, cloth);
  pr(ctx, cx - 5, by + BODY - 1, 10, 1, shadeC(cloth, -25));
  // belt
  pr(ctx, cx - 5, by + BODY, 10, 2, style.accent || pal.accent || PAL.amber);
  pr(ctx, cx - 5, by + BODY + 1, 10, 1, shadeC(style.accent || pal.accent || PAL.amber, -40));
  // sleeves
  pr(ctx, cx - 6, by + 1, 2, 4, cloth);
  pr(ctx, cx + 4, by + 1, 2, 4, cloth);
  // arms at sides
  lineV(ctx, cx - 6, by + 5, 3, shadeC(cloth, -15));
  lineV(ctx, cx + 4, by + 5, 3, shadeC(cloth, -15));
}

function bodyUp(ctx, cx, by, pal, style) {
  pr(ctx, cx - 5, by, 10, BODY, shadeC(pal.cloth, -10));
  pr(ctx, cx - 5, by + BODY - 1, 10, 1, shadeC(pal.cloth, -35));
  pr(ctx, cx - 5, by + BODY, 10, 2, style.accent || pal.accent || PAL.amber);
  lineV(ctx, cx - 6, by + 2, 3, shadeC(pal.cloth, -25));
  lineV(ctx, cx + 4, by + 2, 3, shadeC(pal.cloth, -25));
}

function bodySide(ctx, cx, by, dir, pal, style) {
  const h = dir > 0 ? 1 : -1;
  const ox = cx + h * 3;
  pr(ctx, ox - h * 4, by, 6, BODY, pal.cloth);
  pr(ctx, ox - h * 4, by + BODY - 1, 6, 1, shadeC(pal.cloth, -25));
  pr(ctx, ox - h * 4, by + BODY, 6, 2, style.accent || pal.accent || PAL.amber);
  lineV(ctx, ox - h * 5, by + 2, 3, shadeC(pal.cloth, -15));
}

function legsDown(ctx, cx, footY, pal, style, step) {
  // step: -1 left leg forward (raised), 0 even, 1 right leg forward
  const lx = cx - 4, rx = cx + 1;
  let lh = LEGS, rh = LEGS;
  let ly = footY - BOOT - lh, ry = footY - BOOT - rh;
  if (step < 0) { ly += 1; lh -= 1; }
  if (step > 0) { ry += 1; rh -= 1; }
  pr(ctx, lx, ly, 3, lh, pal.pants);
  pr(ctx, rx, ry, 3, rh, pal.pants);
  pr(ctx, cx - 4, footY - BOOT, 8, BOOT, pal.boots);
  pr(ctx, cx - 3, footY - BOOT - 1, 6, 1, shadeC(pal.boots, 30));
}

function legsUp(ctx, cx, footY, pal, style, step) {
  const lx = cx - 4, rx = cx + 1;
  let lh = LEGS, rh = LEGS;
  let ly = footY - BOOT - lh, ry = footY - BOOT - rh;
  if (step < 0) { ly += 1; lh -= 1; }
  if (step > 0) { ry += 1; rh -= 1; }
  pr(ctx, lx, ly, 3, lh, shadeC(pal.pants, -15));
  pr(ctx, rx, ry, 3, rh, shadeC(pal.pants, -15));
  pr(ctx, cx - 4, footY - BOOT, 8, BOOT, shadeC(pal.boots, -15));
}

function legsSide(ctx, cx, footY, dir, pal, style, step) {
  const h = dir > 0 ? 1 : -1;
  const ox = cx + h * 3;
  let hgh = LEGS;
  let yy = footY - BOOT - hgh;
  if (step < 0) { yy += 1; hgh -= 1; }
  pr(ctx, ox - h * 2, yy, 2, hgh, pal.pants);
  // far leg hint
  pr(ctx, ox - h * 3, yy + 1, 1, hgh - 1, shadeC(pal.pants, -20));
  pr(ctx, ox - h * 2, footY - BOOT, 2, BOOT, pal.boots);
  pr(ctx, ox - h * 3, footY - BOOT, 1, BOOT, shadeC(pal.boots, -15));
}

function hatDown(ctx, cx, hy, pal, style) {
  if (!style.hat) return;
  if (style.hat === 'helm') {
    lineH(ctx, cx - 4, hy - 5, 8, '#4a443a');
    pr(ctx, cx - 4, hy - 4, 8, 1, '#8a8474');
    lineH(ctx, cx - 2, hy - 6, 4, '#6a6454');
  } else if (style.hat === 'veil') {
    lineH(ctx, cx - 5, hy - 5, 10, '#5a4a6a');
    lineV(ctx, cx - 5, hy - 4, 3, '#5a4a6a');
    lineV(ctx, cx + 4, hy - 4, 3, '#5a4a6a');
  }
}

// walk bob offset from phase 0..1
function bobOf(phase) { return Math.sin(phase * Math.PI) * 1.5; }

export function drawPerson(ctx, x, y, s, opt = {}) {
  const pal = opt.palette || PALETTES[opt.paletteIndex || 0] || PALETTES[0];
  const cls = CLASSES[opt.classId];
  const accent = opt.accent || cls?.color || pal.accent || PAL.amber;
  const role = opt.role || '';
  const facing = opt.facing || 'down';
  const walk = opt.walk || 0;
  const t = opt.time || 0;
  const scale = opt.scale || 1;
  const cpal = CHAR_PALS[role] || CHAR_PALS.villager;
  const p = { ...cpal, accent };
  const style = {
    hair: role === 'child' ? 'short' : role === 'elder' ? 'cap' : role === 'seer' ? 'veil' : role === 'witch' ? 'cap' : role === 'guard' ? 'helm' : 'short',
    hat: role === 'guard' ? 'helm' : role === 'seer' ? 'veil' : null,
    accent,
  };

  ctx.save();
  const cx = Math.round(x);
  const footY = Math.round(y);
  const fx = cx - Math.round(8 * scale);
  const fy = footY - Math.round(24 * scale);

  // shadow under feet
  ctx.fillStyle = 'rgba(0,0,0,.35)';
  ctx.beginPath(); ctx.ellipse(cx, footY + 1, 5 * scale, 1.5 * scale, 0, 0, TAU); ctx.fill();

  const phase = walk % 1;
  const step = Math.sin(phase * Math.PI * 2) > 0 ? (walk * 2) % 2 < 1 ? -1 : 1 : 0;
  const bob = walk ? bobOf(phase) : 0;
  const by = footY - BOOT - LEGS - BODY + Math.round(bob);
  const hy = by - HEAD - 2 + Math.round(bob);

  if (facing === 'down') {
    hatDown(ctx, cx, hy - 2, p, style);
    headDown(ctx, cx, hy, p, style);
    bodyDown(ctx, cx, by, p, style);
    legsDown(ctx, cx, footY + Math.round(bob), p, style, step);
  } else if (facing === 'up') {
    legsUp(ctx, cx, footY + Math.round(bob), p, style, step);
    bodyUp(ctx, cx, by, p, style);
    headUp(ctx, cx, hy, p, style);
  } else {
    const dir = facing === 'right' ? 1 : -1;
    legsSide(ctx, cx, footY + Math.round(bob), dir, p, style, step);
    bodySide(ctx, cx, by, dir, p, style);
    headSide(ctx, cx, hy, dir, p, style);
  }

  // role extras
  if (role === 'elder' || role === 'seer') {
    // staff held in left hand (down/side)
    lineV(ctx, cx - 7, hy + 2, 6, '#6a5238');
    px(ctx, cx - 7, hy + 7, accent);
  }
  if (role === 'witch') {
    lineV(ctx, cx - 6, hy + 4, 6, '#6a5238');
    px(ctx, cx - 6, hy + 9, accent);
  }
  if (role === 'smith') {
    px(ctx, cx + 5, by + 4, '#d9c290');
  }
  if (role === 'inn') {
    px(ctx, cx + 5, by + 5, PAL.amber);
  }
  if (cls?.id === 'vanguard' || role === 'guard' || role === 'envoy') {
    ctx.strokeStyle = '#b9c2c9'; ctx.lineWidth = scale;
    ctx.beginPath(); ctx.moveTo(cx + 5, footY - BOOT - 2); ctx.lineTo(cx + 7, hy + 2); ctx.stroke();
  }
  if (role === 'child') {
    // smaller head hint already via shorter body handled by scale
  }
  ctx.restore();
}

// ── pixel portraits (32×40 busts) ────────────────────────────────────────
export function drawPortrait(canvas, member, opts = {}) {
  const ctx = canvas.getContext('2d');
  const dpr = opts.dpr || 1;
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  const W = canvas.width / dpr, H = canvas.height / dpr;
  const pal = paletteFor(member);
  const cls = CLASSES[member.classId];
  const accent = cls?.color || pal.accent;
  const role = (member.role || '') ;

  ctx.clearRect(0, 0, W, H);
  // background: deep shadow with amber rim
  const g = ctx.createLinearGradient(0, 0, W, H);
  g.addColorStop(0, '#1c1824'); g.addColorStop(1, '#0f0d14');
  ctx.fillStyle = g; ctx.fillRect(0, 0, W, H);
  // rim glow
  ctx.fillStyle = withAlpha(accent, .35);
  ctx.beginPath(); ctx.arc(W * .5, H * .3, W * .62, 0, TAU); ctx.fill();
  // shoulders
  ctx.fillStyle = pal.cloth;
  ctx.beginPath();
  ctx.moveTo(W * .16, H * .92);
  ctx.lineTo(W * .16, H * .62);
  ctx.lineTo(W * .42, H * .52);
  ctx.lineTo(W * .58, H * .52);
  ctx.lineTo(W * .84, H * .62);
  ctx.lineTo(W * .84, H * .92);
  ctx.closePath(); ctx.fill();
  ctx.fillStyle = shadeC(pal.cloth, -30);
  pr(ctx, W * .16, H * .86, W * .68, H * .06, shadeC(pal.cloth, -30)); // collar line
  // neck
  ctx.fillStyle = shadeC(pal.skin, -10);
  pr(ctx, W * .44, H * .42, W * .12, H * .14, shadeC(pal.skin, -10));
  // head
  const cx = W * .5, hy = H * .32, hr = W * .17;
  ctx.fillStyle = pal.skin;
  ctx.beginPath(); ctx.ellipse(cx, hy, hr * .82, hr, 0, 0, TAU); ctx.fill();
  // hair
  ctx.fillStyle = pal.hair;
  ctx.beginPath(); ctx.arc(cx, hy - hr * .18, hr * .9, Math.PI * 1.02, Math.PI * 1.98); ctx.fill();
  lineH(ctx, cx - hr * .85, hy - hr * .05, hr * 1.7 > 0 ? hr * 1.7 : -hr * 1.7, pal.hair); // sideburns hint
  // eyes
  ctx.fillStyle = '#221716';
  ctx.beginPath(); ctx.arc(cx - hr * .3, hy + hr * .06, Math.max(1, hr * .055), 0, TAU); ctx.fill();
  ctx.beginPath(); ctx.arc(cx + hr * .3, hy + hr * .06, Math.max(1, hr * .055), 0, TAU); ctx.fill();
  ctx.fillStyle = withAlpha(accent, .9);
  ctx.beginPath(); ctx.arc(cx - hr * .27, hy + hr * .05, Math.max(1, hr * .018), 0, TAU); ctx.fill();
  ctx.beginPath(); ctx.arc(cx + hr * .32, hy + hr * .05, Math.max(1, hr * .018), 0, TAU); ctx.fill();
  // mouth
  ctx.strokeStyle = 'rgba(60,30,25,.5)'; ctx.lineWidth = 1;
  ctx.beginPath(); ctx.arc(cx, hy + hr * .4, hr * .18, .25, Math.PI - .25); ctx.stroke();
  // class mark on forehead
  ctx.fillStyle = withAlpha(accent, .8);
  ctx.beginPath(); ctx.arc(cx, hy - hr * .45, Math.max(1, hr * .09), 0, TAU); ctx.fill();
  // lower fade
  const edge = ctx.createLinearGradient(0, H * .66, 0, H);
  edge.addColorStop(0, 'rgba(0,0,0,0)'); edge.addColorStop(1, 'rgba(0,0,0,.65)');
  ctx.fillStyle = edge; ctx.fillRect(0, 0, W, H);
  // name sigil
  ctx.fillStyle = withAlpha(accent, .5);
  ctx.font = `${Math.round(W * .12)}px Georgia, serif`;
  ctx.textAlign = 'center';
  ctx.fillText(cls?.sigil || '✦', cx, H * .955);
}

export function drawEnemyFace(canvas, def, opts = {}) {
  const ctx = canvas.getContext('2d');
  const dpr = opts.dpr || 1;
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  const W = canvas.width / dpr, H = canvas.height / dpr;
  ctx.clearRect(0, 0, W, H);
  const g = ctx.createLinearGradient(0, 0, W, H);
  g.addColorStop(0, shade(def.color || '#5a4a3a', -10)); g.addColorStop(1, '#0a0d14');
  ctx.fillStyle = g; ctx.fillRect(0, 0, W, H);
  ctx.save();
  ctx.beginPath(); ctx.arc(W / 2, H / 2, W / 2, 0, TAU); ctx.clip();
  const halo = ctx.createRadialGradient(W / 2, H * .55, 0, W / 2, H * .55, W * .5);
  halo.addColorStop(0, withAlpha(def.accent || '#f0a15a', .22)); halo.addColorStop(1, 'rgba(0,0,0,0)');
  ctx.fillStyle = halo; ctx.fillRect(0, 0, W, H);
  drawEnemy(ctx, def, W / 2, H * .94, H * .52, 0, {});
  ctx.restore();
}

export function drawFace(canvas, member, dpr = 1) {
  drawPortrait(canvas, member, { dpr });
}

// ── pixel enemies (battle) ───────────────────────────────────────────────
// Drawn facing the party. (x,y) = feet centre, s = height scale.
export function drawEnemy(ctx, def, x, y, s, t = 0, fx = {}) {
  const col = def.color || '#8a6a4a';
  const acc = def.accent || '#f0a15a';
  const scale = def.size || 1;
  const Hh = s * 1.5 * scale;
  const foot = y + (fx.bob || 0);
  const shake = fx.shake || 0;
  const alpha = fx.alpha ?? 1;
  const flash = fx.flash || 0;
  ctx.save();
  ctx.translate(Math.round(x + shake), Math.round(y));
  ctx.globalAlpha = alpha;
  const body = (c) => flash > 0 ? '#f0e8d0' : c;
  ctx.shadowColor = withAlpha(acc, .35); ctx.shadowBlur = s * .1 * scale;

  if (def.shape === 'wisp') {
    const fy = foot - Hh * .55;
    const g = ctx.createRadialGradient(0, fy, 0, 0, fy, Hh * .3);
    g.addColorStop(0, '#fff1cf'); g.addColorStop(.35, acc); g.addColorStop(1, 'rgba(0,0,0,0)');
    ctx.fillStyle = g; ctx.beginPath(); ctx.arc(0, fy, Hh * .32, 0, TAU); ctx.fill();
    ctx.fillStyle = body(col); ctx.beginPath(); ctx.arc(0, fy, Hh * .14, 0, TAU); ctx.fill();
    ctx.fillStyle = '#2b1810';
    ctx.beginPath(); ctx.arc(-Hh * .06, fy - Hh * .02, s * .02, 0, TAU); ctx.fill();
    ctx.beginPath(); ctx.arc(Hh * .06, fy - Hh * .02, s * .02, 0, TAU); ctx.fill();
  } else if (def.shape === 'wolf') {
    const by = foot - Hh * .34;
    ctx.fillStyle = body(col);
    ctx.beginPath(); ctx.ellipse(0, by, Hh * .3, Hh * .16, -.1, 0, TAU); ctx.fill();
    ctx.strokeStyle = shadeC(col, -30); ctx.lineWidth = s * .06; ctx.lineCap = 'round';
    for (const [ox, oy] of [[-.16, .13], [.15, .12], [-.05, .17], [.25, .17]]) {
      ctx.beginPath(); ctx.moveTo(ox * Hh, by + Hh * .1); ctx.lineTo(ox * Hh + oy * Hh * .7, foot); ctx.stroke();
    }
    ctx.fillStyle = body(shadeC(col, 12));
    ctx.beginPath(); ctx.ellipse(-Hh * .28, by - Hh * .12, Hh * .14, Hh * .12, -.3, 0, TAU); ctx.fill();
    ctx.fillStyle = shadeC(col, -20);
    ctx.beginPath(); ctx.moveTo(-Hh * .28, by - Hh * .22); ctx.lineTo(-Hh * .24, by - Hh * .36); ctx.lineTo(-Hh * .17, by - Hh * .23); ctx.fill();
    ctx.fillStyle = acc; ctx.shadowColor = acc; ctx.shadowBlur = s * .1;
    ctx.beginPath(); ctx.arc(-Hh * .36, by - Hh * .13, s * .02, 0, TAU); ctx.fill();
  } else if (def.shape === 'husk' || def.shape === 'human') {
    const h = Hh * .78;
    const wide = def.shape === 'husk' ? .4 : .34;
    ctx.fillStyle = body(col);
    rr(ctx, -Hh * wide * .55, foot - h, Hh * wide * 1.1, h * .72, s * .05); ctx.fill();
    ctx.fillStyle = shadeC(col, -35);
    rr(ctx, -Hh * .14, foot - h * .35, Hh * .11, h * .35, 2); ctx.fill();
    rr(ctx, Hh * .03, foot - h * .35, Hh * .11, h * .35, 2); ctx.fill();
    ctx.strokeStyle = shadeC(col, 8); ctx.lineWidth = s * .07; ctx.lineCap = 'round';
    ctx.beginPath(); ctx.moveTo(-Hh * wide * .5, foot - h * .85); ctx.lineTo(-Hh * wide * .75, foot - h * .45); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(Hh * wide * .5, foot - h * .85); ctx.lineTo(Hh * wide * .7, foot - h * .5); ctx.stroke();
    ctx.fillStyle = def.shape === 'husk' ? '#c6b89c' : '#e0c8a8';
    ctx.beginPath(); ctx.arc(0, foot - h - s * .03, Hh * .1, 0, TAU); ctx.fill();
    ctx.fillStyle = '#2b211c';
    if (def.shape === 'husk') {
      ctx.beginPath(); ctx.arc(-Hh * .03, foot - h - s * .03, s * .02, 0, TAU); ctx.fill();
      ctx.beginPath(); ctx.arc(Hh * .03, foot - h - s * .03, s * .02, 0, TAU); ctx.fill();
    } else {
      ctx.fillStyle = shadeC(col, -35);
      ctx.beginPath(); ctx.arc(0, foot - h - s * .02, Hh * .12, Math.PI * 1.02, Math.PI * 1.98); ctx.fill();
      ctx.fillStyle = acc;
      ctx.beginPath(); ctx.arc(-Hh * .03, foot - h, s * .015, 0, TAU); ctx.fill();
      ctx.beginPath(); ctx.arc(Hh * .03, foot - h, s * .015, 0, TAU); ctx.fill();
      ctx.strokeStyle = '#cfc6b2'; ctx.lineWidth = s * .03;
      ctx.beginPath(); ctx.moveTo(-Hh * .28, foot - h * .7); ctx.lineTo(-Hh * .48, foot - h * .15); ctx.stroke();
    }
    ctx.fillStyle = withAlpha(acc, .8);
    rr(ctx, -Hh * wide * .5, foot - h * .42, Hh * wide * 1.1, s * .03, 2); ctx.fill();
  } else if (def.shape === 'plant') {
    const baseY = foot;
    ctx.fillStyle = body(shadeC(col, -18));
    ctx.beginPath(); ctx.moveTo(-Hh * .22, baseY); ctx.quadraticCurveTo(-Hh * .34, baseY - Hh * .7, 0, baseY - Hh * .85); ctx.quadraticCurveTo(Hh * .34, baseY - Hh * .7, Hh * .22, baseY); ctx.closePath(); ctx.fill();
    ctx.fillStyle = body(col);
    for (let i = 0; i < 6; i++) {
      const a = -Math.PI + i * Math.PI / 5;
      ctx.beginPath(); ctx.ellipse(Math.cos(a) * Hh * .15, baseY - Hh * .8 + Math.sin(a) * Hh * .07, Hh * .1, Hh * .05, a, 0, TAU); ctx.fill();
    }
    ctx.fillStyle = '#1d2a18'; ctx.beginPath(); ctx.arc(0, baseY - Hh * .8, Hh * .1, 0, TAU); ctx.fill();
  } else if (def.shape === 'toad') {
    const h = Hh * .5;
    ctx.fillStyle = body(col);
    ctx.beginPath(); ctx.ellipse(0, foot - h * .42, Hh * .34, h * .7, 0, 0, TAU); ctx.fill();
    ctx.fillStyle = shadeC(col, 25);
    ctx.beginPath(); ctx.arc(-Hh * .25, foot - h * .95, Hh * .08, 0, TAU); ctx.fill();
    ctx.beginPath(); ctx.arc(-Hh * .06, foot - h * .95, Hh * .08, 0, TAU); ctx.fill();
    ctx.fillStyle = '#10170f';
    ctx.beginPath(); ctx.arc(-Hh * .27, foot - h * .95, s * .03, 0, TAU); ctx.fill();
    ctx.beginPath(); ctx.arc(-Hh * .04, foot - h * .95, s * .03, 0, TAU); ctx.fill();
  } else if (def.shape === 'wraith' || def.shape === 'witch') {
    const h = Hh * .8;
    const float = Math.sin(t * 1.4) * s * .03;
    ctx.fillStyle = body(col);
    ctx.globalAlpha = alpha * .9;
    ctx.beginPath();
    ctx.moveTo(-Hh * .3, foot - h * .15 + float);
    ctx.quadraticCurveTo(-Hh * .4, foot - h * .75 + float, 0, foot - h + float);
    ctx.quadraticCurveTo(Hh * .4, foot - h * .75 + float, Hh * .3, foot - h * .15 + float);
    ctx.lineTo(Hh * .22, foot - h * .02 + float);
    ctx.lineTo(Hh * .1, foot - h * .14 + float);
    ctx.lineTo(0, foot + float);
    ctx.lineTo(-Hh * .14, foot - h * .14 + float);
    ctx.lineTo(-Hh * .24, foot - h * .02 + float);
    ctx.closePath(); ctx.fill();
    ctx.fillStyle = '#171420';
    ctx.beginPath(); ctx.ellipse(-Hh * .02, foot - h * .78 + float, Hh * .12, Hh * .14, 0, 0, TAU); ctx.fill();
    if (def.shape === 'witch') {
      ctx.fillStyle = acc; ctx.shadowColor = acc; ctx.shadowBlur = s * .15;
      ctx.beginPath(); ctx.arc(-Hh * .06, foot - h * .77 + float, s * .025, 0, TAU); ctx.fill();
      ctx.beginPath(); ctx.arc(Hh * .04, foot - h * .77 + float, s * .025, 0, TAU); ctx.fill();
      ctx.fillStyle = body(shadeC(col, -18));
      ctx.beginPath(); ctx.moveTo(-Hh * .22, foot - h * .85 + float); ctx.lineTo(0, foot - h * 1.2 + float); ctx.lineTo(Hh * .16, foot - h * .85 + float); ctx.closePath(); ctx.fill();
    } else {
      ctx.fillStyle = acc; ctx.shadowColor = acc; ctx.shadowBlur = s * .15;
      ctx.beginPath(); ctx.arc(-Hh * .04, foot - h * .79 + float, s * .02, 0, TAU); ctx.fill();
      ctx.beginPath(); ctx.arc(Hh * .02, foot - h * .79 + float, s * .02, 0, TAU); ctx.fill();
    }
  } else if (def.shape === 'golem') {
    const h = Hh * .8;
    ctx.fillStyle = body(col);
    rr(ctx, -Hh * .28, foot - h, Hh * .56, h, s * .05); ctx.fill();
    ctx.fillStyle = shadeC(col, -18);
    rr(ctx, -Hh * .4, foot - h * .9, Hh * .16, h * .5, s * .04); ctx.fill();
    rr(ctx, Hh * .24, foot - h * .9, Hh * .16, h * .5, s * .04); ctx.fill();
    ctx.strokeStyle = acc; ctx.lineWidth = s * .025; ctx.shadowColor = acc; ctx.shadowBlur = s * .1;
    ctx.beginPath(); ctx.moveTo(-Hh * .18, foot - h * .9); ctx.lineTo(-Hh * .04, foot - h * .68); ctx.lineTo(-Hh * .12, foot - h * .48); ctx.lineTo(Hh * .04, foot - h * .28); ctx.stroke();
    ctx.fillStyle = acc;
    ctx.beginPath(); ctx.arc(-Hh * .06, foot - h - Hh * .02, s * .02, 0, TAU); ctx.fill();
    ctx.beginPath(); ctx.arc(Hh * .06, foot - h - Hh * .02, s * .02, 0, TAU); ctx.fill();
  } else if (def.shape === 'knight' || def.shape === 'king') {
    const h = Hh * .82 * (def.shape === 'king' ? 1.1 : 1);
    const wide = def.shape === 'king' ? .42 : .36;
    ctx.fillStyle = withAlpha(shadeC(col, -35), .9);
    ctx.beginPath(); ctx.moveTo(-Hh * wide * .5, foot - h * .9); ctx.lineTo(-Hh * wide, foot - h * .02); ctx.lineTo(Hh * wide * .2, foot - h * .06); ctx.closePath(); ctx.fill();
    ctx.fillStyle = body(col);
    rr(ctx, -Hh * wide * .6, foot - h, Hh * wide * 1.2, h * .7, s * .05); ctx.fill();
    ctx.fillStyle = shadeC(col, 18);
    ctx.beginPath(); ctx.moveTo(-Hh * wide * .6, foot - h + s * .02); ctx.lineTo(0, foot - h * .78); ctx.lineTo(Hh * wide * .6, foot - h + s * .02); ctx.fill();
    ctx.fillStyle = shadeC(col, -25);
    rr(ctx, -Hh * .15, foot - h * .34, Hh * .12, h * .34, 2); ctx.fill();
    rr(ctx, Hh * .03, foot - h * .34, Hh * .12, h * .34, 2); ctx.fill();
    ctx.fillStyle = shadeC(col, 6);
    rr(ctx, -Hh * wide * .75, foot - h * .8, Hh * .14, h * .38, s * .03); ctx.fill();
    ctx.fillStyle = shadeC(col, 25);
    ctx.beginPath(); ctx.arc(0, foot - h - s * .02, Hh * .11, Math.PI, TAU); ctx.fill();
    rr(ctx, -Hh * .11, foot - h - s * .03, Hh * .22, Hh * .11, s * .02); ctx.fill();
    ctx.fillStyle = '#1a120e';
    rr(ctx, -Hh * .07, foot - h + Hh * .02, Hh * .14, s * .02, 1); ctx.fill();
    ctx.fillStyle = acc; ctx.shadowColor = acc; ctx.shadowBlur = s * .12;
    ctx.beginPath(); ctx.arc(-Hh * .04, foot - h + Hh * .035, s * .012, 0, TAU); ctx.fill();
    ctx.beginPath(); ctx.arc(Hh * .04, foot - h + Hh * .035, s * .012, 0, TAU); ctx.fill();
    ctx.strokeStyle = '#cfd6da'; ctx.lineWidth = s * .04;
    ctx.beginPath(); ctx.moveTo(-Hh * wide * .75, foot - h * .38); ctx.lineTo(-Hh * wide * .75 - Hh * .16, foot + s * .05); ctx.stroke();
    if (def.shape === 'king') {
      ctx.fillStyle = acc; ctx.shadowColor = acc; ctx.shadowBlur = s * .18;
      const cy = foot - h - Hh * .16;
      ctx.beginPath(); ctx.moveTo(-Hh * .12, cy); ctx.lineTo(-Hh * .1, cy - Hh * .07); ctx.lineTo(-Hh * .05, cy - Hh * .02); ctx.lineTo(0, cy - Hh * .1); ctx.lineTo(Hh * .05, cy - Hh * .02); ctx.lineTo(Hh * .1, cy - Hh * .07); ctx.lineTo(Hh * .12, cy); ctx.closePath(); ctx.fill();
    }
  } else {
    ctx.fillStyle = body(col);
    ctx.beginPath(); ctx.arc(0, foot - Hh * .4, Hh * .26, 0, TAU); ctx.fill();
  }
  ctx.restore();
}

// ── class art for creation screen (pixel) ────────────────────────────────
export function drawClassArt(canvas, classId, paletteIdx, opts = {}) {
  const ctx = canvas.getContext('2d');
  const dpr = opts.dpr || 1;
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  const W = canvas.width / dpr, H = canvas.height / dpr;
  const cls = CLASSES[classId];
  const pal = PALETTES[paletteIdx] || PALETTES[0];
  ctx.clearRect(0, 0, W, H);
  const g = ctx.createLinearGradient(0, 0, 0, H);
  g.addColorStop(0, withAlpha(cls.color, .16)); g.addColorStop(1, 'rgba(8,11,17,0)');
  ctx.fillStyle = g; ctx.fillRect(0, 0, W, H);
  ctx.strokeStyle = withAlpha(cls.color, .18); ctx.lineWidth = 1;
  for (let i = 0; i < 3; i++) {
    ctx.beginPath(); ctx.arc(W / 2, H * .55, H * (.2 + i * .11), 0, TAU); ctx.stroke();
  }
  const member = { classId, palette: paletteIdx, name: cls.name };
  drawPerson(ctx, W / 2, H * .94, H * .32, {
    classId, palette: pal, role: '', facing: 'down', time: opts.time || 0, scale: 1,
  });
}

function shadeC(c, amt) { return shade(c, amt); }

// ── Tile-based world renderer (16-bit JRPG style) ────────────────────────
// 320×180 logical viewport, 16×16 tiles, nearest-neighbour pixels.
// Draw order: background layer → ground tiles → y-sorted objects/characters
// → foreground layer (eaves, awnings, branches) for FFVI-style depth.
import { state } from '../state.js';
import { PAL, TILE, VW, VH, hash2, tileCanvas, drawWindow, drawText, pr, lineV, lineH, px } from './pixel.js';
import { drawPerson } from './art.js';

const T = TILE;

// ── tile art ─────────────────────────────────────────────────────────────
function tileGrass(t, h, tx, ty) {
  const n = hash2(tx, ty);
  pr(t, 0, 0, T, T, n > .5 ? PAL.grass : PAL.grassD);
  if (n > .65) {
    pr(t, 3 + (tx * 3 % 5), 10 + (ty * 2 % 4), 2, 2, PAL.grassL);
    pr(t, 10 + (ty * 3 % 4), 4 + (tx % 3), 1, 2, shade(PAL.grassD, -25));
  }
  // random tufts
  if (n > .85) pr(t, 7 + (tx % 2), 12, 1, 2, PAL.grassD);
}
function tilePath(t, h, tx, ty) {
  const n = hash2(tx * 2, ty * 3);
  pr(t, 0, 0, T, T, PAL.pathD);
  // worn cobble / dirt stones
  const stones = [[1, 2], [5, 1], [9, 3], [13, 2], [3, 9], [7, 10], [11, 8], [14, 11], [1, 14], [8, 14], [12, 14]];
  for (const [sx, sy] of stones) {
    const w = 2 + (sx % 2), hh = 1 + (sy % 2);
    pr(t, sx, sy, w, hh, n > .45 ? PAL.path : PAL.pathL);
  }
  if (hash2(tx, ty) > .75) pr(t, 8 + (tx % 2), 14, 2, 1, shade(PAL.pathD, -30));
}
function tileStone(t, h, tx, ty) {
  const n = hash2(tx, ty);
  pr(t, 0, 0, T, T, PAL.stoneD);
  lineH(t, 0, 4, T, PAL.stone); lineH(t, 0, 11, T, PAL.stone);
  lineV(t, 4, 0, T, PAL.stone); lineV(t, 11, 0, T, PAL.stone);
  pr(t, 0, 0, T, 1, PAL.stoneL);
  pr(t, 0, T - 1, T, 1, shade(PAL.stoneD, -20));
  if (n > .6) pr(t, 7 + (tx % 2), 7 + (ty % 2), 1, 1, PAL.stoneL);
}
function tileFlowers(t, h, tx, ty) {
  const n = hash2(tx * 5, ty);
  pr(t, 0, 0, T, T, PAL.grass);
  const heads = [];
  if (n > .4) heads.push([4, 7]);
  if (n > .6) heads.push([11, 5]);
  if (n > .8) heads.push([7, 9]);
  for (const [fx, fy] of heads) {
    const hc = (fx + fy * 7) % 2 ? PAL.flower : PAL.flowerL;
    pr(t, fx, fy, 2, 2, hc);
    pr(t, fx + 1, fy + 1, 1, 1, '#5a3a2a');
  }
  pr(t, 3 + (tx % 3), 13, 1, 2, PAL.grassD);
}
function tileTree(t, h, tx, ty) {
  const n = hash2(tx * 1.3, ty * 1.7);
  pr(t, 0, 0, T, T, PAL.shadow);
  // trunk
  lineV(t, 7, 10, 6, '#4a3526');
  lineV(t, 8, 10, 6, '#3a2a22');
  pr(t, 6, 16, 4, 1, '#3a2a22'); // roots
  // canopy
  const leaf = shade(PAL.leaf, Math.round((n - .5) * 14));
  const leaf2 = shade(PAL.leafL, Math.round((n - .5) * 10));
  const cx = 8;
  ctxFillCircle(t, cx, 4, 5, leaf);
  ctxFillCircle(t, cx + 2, 5, 4, leaf);
  ctxFillCircle(t, cx - 2, 6, 4, leaf2);
  ctxFillCircle(t, cx, 2, 3, leaf2);
  pr(t, cx - 1, 0, 2, 2, shade(PAL.leaf, -20));
}
function tileTreeBig(t, h, tx, ty) {
  const n = hash2(tx * 7, ty * 11);
  pr(t, 0, 0, T, T, PAL.shadowD);
  lineV(t, 7, 12, 4, '#4a3526');
  lineV(t, 8, 12, 4, '#3a2a22');
  pr(t, 6, 16, 4, 1, '#3a2a22');
  const leaf = shade(PAL.leaf, Math.round((n - .5) * 14));
  const cx = 8;
  ctxFillCircle(t, cx, 3, 6, leaf);
  ctxFillCircle(t, cx + 3, 4, 5, leaf);
  ctxFillCircle(t, cx - 3, 4, 5, leaf);
  ctxFillCircle(t, cx, 0, 4, shade(PAL.leafL, 10));
  pr(t, cx - 1, 0, 2, 1, shade(PAL.leaf, -20));
  // highlight rim
  pr(t, cx + 4, 3, 1, 1, PAL.leafL);
}
function tileHouseRoof(t, h, tx, ty) {
  const n = hash2(tx * 3, ty * 5);
  pr(t, 0, 0, T, T, PAL.roofD);
  // thatch rows
  const base = n > .5 ? PAL.roof : PAL.roofD;
  for (let ry = 0; ry < T; ry += 3) {
    const shadeRow = hash2(tx, ty + ry) > .5 ? PAL.roofL : base;
    lineH(t, 0, ry, T, shadeRow);
  }
  // ridge line
  lineH(t, 0, 2, T, PAL.roofL);
  // eaves shadow
  pr(t, 0, T - 1, T, 1, '#1a1410');
}
function tileHouseWall(t, h, tx, ty, hasWindow) {
  const n = hash2(tx * 9, ty * 7);
  pr(t, 0, 0, T, T, PAL.timber);
  // timber beams every 4px
  for (let bx = 0; bx < T; bx += 4) lineV(t, bx, 0, T, PAL.timberD);
  lineH(t, 0, 0, T, PAL.timberD);
  lineH(t, 0, T - 1, T, shade(PAL.timberD, -25));
  if (hasWindow) {
    // window 4×4 centered
    const wx = 6, wy = 2;
    pr(t, wx, wy, 4, 4, '#171e24');
    lineV(t, wx + 2, wy, 4, '#d9b46a');
    lineH(t, wx, wy + 2, 4, '#d9b46a');
    // sill
    pr(t, wx - 1, wy + 4, 6, 1, PAL.timberL);
    // window glow at dusk handled by light pass; here a warm hint
    pr(t, wx + 1, wy + 1, 2, 2, '#ffcf8a');
  }
}
function tileHouseDoor(t, h, tx, ty) {
  pr(t, 0, 0, T, T, '#20150f');
  lineV(t, 1, 0, T, '#3a2a1d');
  lineV(t, T - 2, 0, T, '#3a2a1d');
  lineH(t, 0, 0, T, '#3a2a1d');
  lineH(t, 0, T - 1, T, '#17100a');
  // door panel planks
  lineH(t, 1, 4, 6, '#2a1c12');
  lineH(t, 1, 9, 6, '#2a1c12');
  lineH(t, 1, 14, 6, '#2a1c12');
  // knob
  pr(t, 10, 8, 1, 1, PAL.amber);
}
function tileBrazier(t, h, tx, ty, lit, now) {
  pr(t, 0, 0, T, T, PAL.shadow);
  const cx = 8, base = 14;
  // bowl
  ctxFillEllipse(t, cx, base + 1, 3, 2, '#3f342b');
  pr(t, cx - 1, base - 2, 2, 1, '#4b3f33');
  ctxFillEllipse(t, cx, base - 2, 2, 1, '#4b3f33');
  ctxFillEllipse(t, cx, base - 3, 2, 1, '#2a2420');
  if (lit) {
    const f = Math.sin(now / 90 + tx) * .3;
    pr(t, cx - 1, base - 4, 1, 2, '#ffcf7a');
    pr(t, cx, base - 6, 1, 2, '#ffe0b0');
    pr(t, cx + 1, base - 4 - (f > 0 ? 1 : 0), 1, 2, '#ffcf7a');
    pr(t, cx, base - 7 + (f > 0 ? -1 : 0), 1, 1, '#fff8e0');
    // glow pixels
    if (Math.sin(now / 110 + tx) > .6) pr(t, cx - 2, base - 5, 1, 1, '#ffd08a');
    if (Math.sin(now / 110 + tx + 1) > .6) pr(t, cx + 2, base - 6, 1, 1, '#ffd08a');
  } else {
    ctxFillEllipse(t, cx, base - 3, 2, 1, '#2a2420');
  }
}
function tileCrystal(t, h, tx, ty, now) {
  pr(t, 0, 0, T, T, PAL.shadow);
  const cx = 8, cy = 7 + Math.sin(now / 700) * .5;
  ctxFillPoly(t, [[cx, cy - 4], [cx + 2, cy - 1], [cx + 1, cy + 3], [cx - 1, cy + 3], [cx - 2, cy - 1]], PAL.waterL);
  ctxFillPoly(t, [[cx, cy - 3], [cx + 1, cy - 1], [cx, cy + 2], [cx - 1, cy - 1]], '#e0f4f0');
  pr(t, cx, cy - 4, 1, 1, '#ffffff');
  ctxFillEllipse(t, cx, 14, 3, 1, 'rgba(0,0,0,.35)');
}
function tileChest(t, h, tx, ty, opened) {
  pr(t, 0, 0, T, T, PAL.shadow);
  const cx = 8, base = 14;
  ctxFillEllipse(t, cx, base + 1, 3, 1, 'rgba(0,0,0,.35)');
  pr(t, cx - 4, base - 6, 8, 6, '#6b4a2c');
  pr(t, cx - 4, base - 4, 8, 2, '#4c321d');
  lineH(t, cx - 4, base - 6, 8, '#d9b46a');
  lineV(t, cx - 4, base - 6, 6, '#d9b46a');
  lineV(t, cx + 3, base - 6, 6, '#d9b46a');
  lineH(t, cx - 4, base - 1, 8, '#d9b46a');
  if (opened) {
    ctxFillPoly(t, [[cx - 4, base - 6], [cx - 6, base - 7], [cx + 6, base - 7], [cx + 4, base - 6]], '#2a1c12');
    pr(t, cx - 4, base - 7, 8, 1, '#17100a');
  } else {
    pr(t, cx, base - 7, 1, 1, '#d9b46a');
    pr(t, cx, base - 8, 1, 1, '#ffcf7a');
  }
}
function tileSign(t, h, tx, ty) {
  pr(t, 0, 0, T, T, PAL.shadow);
  lineV(t, 8, 9, 5, '#4a3725');
  pr(t, 5, 3, 6, 4, '#6b5237');
  lineH(t, 5, 3, 6, '#c9a97a');
  lineH(t, 5, 6, 6, '#c9a97a');
  lineV(t, 5, 3, 4, '#c9a97a');
  lineV(t, 10, 3, 4, '#c9a97a');
  // little text marks
  pr(t, 7, 5, 1, 1, '#e8ddc8');
  pr(t, 9, 5, 1, 1, '#e8ddc8');
}
function tileLamp(t, h, tx, ty, lit, now) {
  pr(t, 0, 0, T, T, PAL.shadow);
  lineV(t, 8, 10, 6, '#3e332a');
  pr(t, 7, 10, 2, 1, '#3e332a');
  const fy = 4;
  if (lit) {
    const gl = .7 + Math.sin(now / 90 + tx) * .15;
    ctxFillCircle(t, 8, fy, 3, 'rgba(255,210,130,' + gl + ')');
    ctxFillCircle(t, 8, fy, 2, '#ffe0b0');
    pr(t, 8, fy, 1, 1, '#fff8e0');
  } else {
    ctxFillCircle(t, 8, fy, 2, '#3e332a');
    ctxStrokeCircle(t, 8, fy, 2, 'rgba(255,200,120,.3)');
  }
  ctxFillEllipse(t, 8, 14, 2, 1, 'rgba(0,0,0,.35)');
}
function tileTent(t, h, tx, ty) { // market stall
  pr(t, 0, 0, T, T, PAL.shadow);
  const cx = 8, base = 14;
  ctxFillEllipse(t, cx, base + 1, 3, 1, 'rgba(0,0,0,.35)');
  // awning
  ctxFillPoly(t, [[cx - 6, base], [cx, base - 7], [cx + 6, base]], '#b89a72');
  ctxFillPoly(t, [[cx - 6, base], [cx - 2, base - 4], [cx + 2, base - 4], [cx + 6, base]], '#a67c5c');
  lineH(t, cx - 6, base - 2, 13, '#8a6544');
  // goods on stall
  pr(t, cx - 4, base - 5, 1, 1, PAL.amber);
  pr(t, cx + 2, base - 5, 1, 1, '#c78a8a');
  pr(t, cx - 1, base - 6, 1, 1, '#8fbf7a');
  pr(t, cx + 4, base - 4, 1, 1, PAL.violet);
}
function tileWater(t, h, tx, ty, deep, now) {
  const base = deep ? PAL.waterD : PAL.water;
  const n = hash2(tx, ty);
  pr(t, 0, 0, T, T, base);
  const off = Math.sin(now / 700 + tx * .7 + ty * .5);
  lineH(t, 2, 6 + (off > 0 ? 0 : 1), 4, PAL.waterL);
  lineH(t, 9, 9 + (off < 0 ? 0 : 1), 4, shade(base, 25));
  pr(t, 13, 4 + (off > 0 ? 1 : 0), 1, 1, PAL.waterL);
  pr(t, 1, 12 + (off < 0 ? 1 : 0), 1, 1, PAL.waterL);
  if (deep) {
    pr(t, 4, 12, 2, 1, shade(base, -20));
    pr(t, 10, 7, 2, 1, shade(base, -20));
  }
}
function tileRock(t, h, tx, ty) {
  const n = hash2(tx * 5, ty * 3);
  pr(t, 0, 0, T, T, PAL.shadow);
  ctxFillPoly(t, [[5, 15], [4, 10], [6, 7], [10, 5], [13, 8], [14, 11], [12, 15]], PAL.rock || PAL.stoneD);
  ctxFillPoly(t, [[6, 9], [9, 7], [11, 8], [9, 10], [7, 11]], '#b8b4a8');
}
function tileFence(t, h, tx, ty) {
  pr(t, 0, 0, T, T, PAL.shadow);
  pr(t, 0, 12, T, 1, '#5b442e');
  lineV(t, 2, 4, 6, '#5b442e');
  lineV(t, 13, 4, 6, '#5b442e');
  lineH(t, 0, 7, T, '#5b442e');
  lineH(t, 0, 10, T, '#5b442e');
}
function tilePortal(t, h, tx, ty, accent, now) {
  pr(t, 0, 0, T, T, '#1a1218');
  const cx = 8, cy = 10;
  const r = 2 + Math.sin(now / 500) * .5;
  ctxFillCircle(t, cx, cy, r, accent);
  ctxFillCircle(t, cx, cy, r - 1, '#1a1218');
  ctxStrokeCircle(t, cx, cy, r + 1, withAlpha(acc, .6));
}
function tileLava(t, h, tx, ty, now) {
  pr(t, 0, 0, T, T, '#2c1408');
  const f = Math.sin(now / 100 + tx * 2);
  pr(t, 4, 8 + (f > 0 ? 0 : 1), 3, 1, '#f0774d');
  pr(t, 9, 11 + (f < 0 ? 0 : 1), 3, 1, '#ffb56a');
  pr(t, 2, 14, 1, 1, '#e0632c');
  pr(t, 13, 5, 1, 1, '#e0632c');
}

// tiny geometry helpers
function ctxFillCircle(t, cx, cy, r, c) {
  t.fillStyle = c;
  for (let dy = -r; dy <= r; dy++) for (let dx = -r; dx <= r; dx++) {
    if (dx * dx + dy * dy <= r * r) t.fillRect(cx + dx, cy + dy, 1, 1);
  }
}
function ctxStrokeCircle(t, cx, cy, r, c) {
  t.strokeStyle = c;
  t.beginPath(); t.arc(cx, cy, r, 0, TAU); t.stroke();
}
function ctxFillEllipse(t, cx, cy, rx, ry, c) {
  t.fillStyle = c;
  for (let dy = -ry; dy <= ry; dy++) for (let dx = -rx; dx <= rx; dx++) {
    if ((dx * dx) / (rx * rx) + (dy * dy) / (ry * ry) <= 1) t.fillRect(cx + dx, cy + dy, 1, 1);
  }
}
function ctxFillPoly(t, pts, c) {
  t.fillStyle = c;
  // scanline fill over bounding box
  let minX = Infinity, maxX = -Infinity, minY = Infinity, maxY = -Infinity;
  for (const p of pts) { minX = Math.min(minX, p[0]); maxX = Math.max(maxX, p[0]); minY = Math.min(minY, p[1]); maxY = Math.max(maxY, p[1]); }
  for (let py = minY; py <= maxY; py++) {
    const xs = [];
    const n = pts.length;
    for (let i = 0, j = n - 1; i < n; j = i++) {
      const [xi, yi] = pts[i], [xj, yj] = pts[j];
      if ((yi > py) !== (yj > py)) xs.push((xj - xi) * (py - yi) / (yj - yi) + xi);
    }
    xs.sort((a, b) => a - b);
    for (let k = 0; k < xs.length; k += 2) {
      for (let sx = Math.ceil(xs[k]); sx <= Math.floor(xs[k + 1]); sx++) t.fillRect(sx, py, 1, 1);
    }
  }
}

// build the tile palette cache per ambient
function buildTiles(ambient) {
  const p = ambientPals[ambient] || ambientPals.village;
  const tiles = {
    '.': () => tileCanvas(`tile:${ambient}:.`, T, T, (c) => tileGrass(c, T, 0, 0)),
    ',': () => tileCanvas(`tile:${ambient}:,`, T, T, (c) => { tileGrass(c, T, 0, 0); pr(c, 6, 13, 1, 4, shade(p.grassD, -15)); } ),
    '"': () => tileCanvas(`tile:${ambient}:"`, T, T, (c) => tileFlowers(c, T, 0, 0)),
    '=': () => tileCanvas(`tile:${ambient}:=`, T, T, (c) => tileStone(c, T, 0, 0)),
    '_': () => tileCanvas(`tile:${ambient}:_`, T, T, (c) => tilePath(c, T, 0, 0)),
    's': () => tileCanvas(`tile:${ambient}:s`, T, T, (c) => { pr(c, 0, 0, T, T, '#b8a488'); pr(c, 2, 10, 1, 2, '#a89078'); } ),
    'x': () => tileCanvas(`tile:${ambient}:x`, T, T, (c) => { pr(c, 0, 0, T, T, '#3a3330'); for (let i = 0; i < 6; i++) pr(c, 1 + (i * 3 % 14), 6 + (i % 4), 1, 1, '#282220'); } ),
    'b': () => tileCanvas(`tile:${ambient}:b`, T, T, (c) => { pr(c, 0, 3, T, 10, '#4b3b2c'); lineH(c, 0, 3, T, '#3a2a1d'); lineH(c, 0, 12, T, '#3a2a1d'); pr(c, 0, 5, T, 1, 'rgba(255,255,255,.06)'); } ),
    'w': () => tileCanvas(`tile:${ambient}:w`, T, T, (c) => tileWater(c, T, 0, 0, false, 0)),
    '~': () => tileCanvas(`tile:${ambient}:~`, T, T, (c) => tileWater(c, T, 0, 0, true, 0)),
    'v': () => tileCanvas(`tile:${ambient}:v`, T, T, (c) => tileLava(c, T, 0, 0, 0)),
    'H': () => tileCanvas(`tile:${ambient}:H`, T, T, (c) => tileHouseWall(c, T, 0, 0, false)),
    'h': () => tileCanvas(`tile:${ambient}:h`, T, T, (c) => tileHouseRoof(c, T, 0, 0)),
    'D': () => tileCanvas(`tile:${ambient}:D`, T, T, (c) => tileHouseDoor(c, T, 0, 0)),
    'W': () => tileCanvas(`tile:${ambient}:W`, T, T, (c) => { pr(c, 0, 0, T, T, '#3a322a'); lineV(c, 0, 0, T, '#28221c'); lineV(c, T - 1, 0, T, '#28221c'); lineH(c, 0, 0, T, '#28221c'); lineH(c, 0, T - 1, T, '#14100a'); lineV(c, 4, 0, T, '#28221c'); lineV(c, T - 5, 0, T, '#28221c'); } ),
    'L': () => tileCanvas(`tile:${ambient}:L`, T, T, (c) => tileLamp(c, T, 0, 0, false, 0)),
    'A': () => tileCanvas(`tile:${ambient}:A`, T, T, (c) => { pr(c, 0, 0, T, T, '#4a463c'); ctxFillPoly(c, [[4, 15], [3, 11], [5, 9], [8, 6], [11, 9], [13, 11], [12, 15]], '#5a564d'); pr(c, 7, 4, 2, 2, '#807a6c'); } ),
    'S': () => tileCanvas(`tile:${ambient}:S`, T, T, (c) => tileCrystal(c, T, 0, 0, 0)),
    'C': () => tileCanvas(`tile:${ambient}:C`, T, T, (c) => tileChest(c, T, 0, 0, false)),
    'o': () => tileCanvas(`tile:${ambient}:o`, T, T, (c) => tileBrazier(c, T, 0, 0, false, 0)),
    'i': () => tileCanvas(`tile:${ambient}:i`, T, T, (c) => tileSign(c, T, 0, 0)),
    'f': () => tileCanvas(`tile:${ambient}:f`, T, T, (c) => tileFence(c, T, 0, 0)),
    'g': () => tileCanvas(`tile:${ambient}:g`, T, T, (c) => { pr(c, 0, 0, T, T, PAL.shadow); ctxFillPoly(c, [[4, 15], [4, 10], [6, 8], [8, 9], [10, 8], [12, 10], [12, 15]], '#5f5c53'); lineH(c, 6, 13, 2, 'rgba(255,255,255,.1)'); } ),
    't': () => tileCanvas(`tile:${ambient}:t`, T, T, (c) => { pr(c, 0, 0, T, T, PAL.shadow); ctxFillEllipse(c, 8, 11, 2, 2, '#4a3526'); pr(c, 7, 11, 4, 1, '#3a2a1f'); ctxFillEllipse(c, 8, 9, 2, 1, '#6b4e35'); } ),
    'n': () => tileCanvas(`tile:${ambient}:n`, T, T, (c) => tileTent(c, T, 0, 0)),
    'B': () => tileCanvas(`tile:${ambient}:B`, T, T, (c) => { pr(c, 0, 0, T, T, PAL.shadow); pr(c, 6, 12, 4, 1, '#b7ad95'); pr(c, 5, 11, 1, 1, '#b7ad95'); pr(c, 9, 11, 1, 1, '#b7ad95'); } ),
    '#': () => tileCanvas(`tile:${ambient}:#`, T, T, (c) => tileTree(c, T, 0, 0)),
    'T': () => tileCanvas(`tile:${ambient}:T`, T, T, (c) => tileTreeBig(c, T, 0, 0)),
    'r': () => tileCanvas(`tile:${ambient}:r`, T, T, (c) => tileRock(c, T, 0, 0)),
    'R': () => tileCanvas(`tile:${ambient}:R`, T, T, (c) => tileRock(c, T, 0, 0)),
    'P': () => tileCanvas(`tile:${ambient}:P`, T, T, (c) => tilePortal(c, T, 0, 0, p.accent, 0)),
    'e': () => tileCanvas(`tile:${ambient}:e`, T, T, (c) => { pr(c, 0, 0, T, T, '#080a12'); pr(c, 2, 8, T - 4, 1, '#1a1824'); } ),
  };
  return tiles;
}

// animated tiles need re-draw each frame: braziers, lamps, water, portal
function drawTile(ctx, ch, dx, dy, ambient, now, zoneState) {
  const p = ambientPals[ambient] || ambientPals.village;
  const key = `${ambient}:${ch}`;
  let tiles = tileCache.get(key);
  if (!tiles) { tiles = buildTiles(ambient); tileCache.set(key, tiles); }
  const t = tiles[ch];
  if (!t) return;
  // static tiles: draw from cache
  const isAnim = ch === 'o' || ch === 'L' || ch === 'w' || ch === '~' || ch === 'v' || ch === 'P';
  if (isAnim) {
    const c = document.createElement('canvas'); c.width = T; c.height = T;
    const tc = c.getContext('2d'); tc.imageSmoothingEnabled = false;
    t(tc, T, 0, 0);
    if (ch === 'o') tileBrazier(tc, T, 0, 0, zoneState.litBraziers ? zoneState.litBraziers.has(`${dx / T},${dy / T}`) : false, now);
    else if (ch === 'L') tileLamp(tc, T, 0, 0, true, now);
    else if (ch === 'w' || ch === '~') tileWater(tc, T, 0, 0, ch === '~', now);
    else if (ch === 'v') tileLava(tc, T, 0, 0, now);
    else if (ch === 'P') tilePortal(tc, T, 0, 0, p.accent, now);
    ctx.drawImage(c, dx | 0, dy | 0);
  } else {
    ctx.drawImage(t(), dx | 0, dy | 0);
  }
}

const ambientPals = {
  village: { grass: PAL.grass, grassD: PAL.grassD, grassL: PAL.grassL, path: PAL.path, pathD: PAL.pathD, pathL: PAL.pathL, stone: PAL.stone, stoneD: PAL.stoneD, wall: PAL.timber, roof: PAL.roof, roof2: PAL.roofD, rock: PAL.stoneD, leaf: PAL.leaf, leaf2: PAL.leafL, trunk: '#4a3526', accent: PAL.amber },
  plains: { grass: PAL.grass, grassD: PAL.grassD, grassL: PAL.grassL, path: PAL.path, pathD: PAL.pathD, pathL: PAL.pathL, stone: PAL.stone, stoneD: PAL.stoneD, wall: PAL.timber, roof: PAL.roof, roof2: PAL.roofD, rock: PAL.stoneD, leaf: PAL.leaf, leaf2: PAL.leafL, trunk: '#4a3526', accent: '#f0b45e' },
  forest: { grass: '#3a5a32', grassD: '#283e2d', grassL: '#6a8a5a', path: '#5f523a', pathD: '#4a422e', pathL: '#8a7e5a', stone: '#5d6252', stoneD: '#4e5445', wall: '#756a51', roof: '#46322a', roof2: '#5a4033', rock: '#4c4f45', leaf: '#3a5d38', leaf2: '#548a4e', trunk: '#3f2e21', accent: '#78d5c0' },
  mire: { grass: '#3a4a44', grassD: '#31443a', grassL: '#5a7a6e', path: '#56513f', pathD: '#464234', pathL: '#8a7e6a', stone: '#555d54', stoneD: '#474f47', wall: '#5f5a48', roof: '#3d302b', roof2: '#4f3e33', rock: '#474d46', leaf: '#405a42', leaf2: '#5a7a5e', trunk: '#3c2f26', accent: '#8fd0b0' },
  peaks: { grass: '#443938', grassD: '#3a3130', grassL: '#6a5e5a', path: '#5e544c', pathD: '#4a423d', pathL: '#8a7e7a', stone: '#5a504a', stoneD: '#4a423d', wall: '#625046', roof: '#3f2c28', roof2: '#523832', rock: '#51443c', leaf: '#564139', leaf2: '#6a5a52', trunk: '#3a2b24', accent: '#ff9257' },
  citadel: { grass: '#30323c', grassD: '#292b34', grassL: '#5a5a72', path: '#3b3c46', pathD: '#33343d', pathL: '#6a6a82', stone: '#45464f', stoneD: '#383943', wall: '#3e3f49', roof: '#32323c', roof2: '#3e3e49', rock: '#3f4049', leaf: '#44454e', leaf2: '#5a5a72', trunk: '#2c2c32', accent: '#b79bea' },
};

// ── main renderer ────────────────────────────────────────────────────────
export function renderWorld(ctx, W, H, view) {
  const { zone, camx, camy, player, npcs, now, lights, drawables } = view;
  const ambient = zone.ambient || 'village';
  const p = ambientPals[ambient] || ambientPals.village;
  ctx.clearRect(0, 0, W, H);
  ctx.fillStyle = '#06080c';
  ctx.fillRect(0, 0, W, H);

  const ox = -((camx | 0) % T) - T;
  const oy = -((camy | 0) % T) - T;
  const tx0 = Math.floor(camx / T) - 1;
  const ty0 = Math.floor(camy / T) - 1;
  const tx1 = Math.min(zone.map.w - 1, Math.ceil((camx + W) / T) + 1);
  const ty1 = Math.min(zone.map.h - 1, Math.ceil((camy + H) / T) + 1);

  // background: distant ridge behind the village
  if (ambient === 'village') {
    drawDistantRidge(ctx, W, H, now);
  }

  // ground
  for (let ty = ty0; ty <= ty1; ty++) {
    const sy = ty * T - camy;
    for (let tx = tx0; tx <= tx1; tx++) {
      const ch = zone.map.g[ty][tx];
      if (ch === 'e') continue;
      drawTile(ctx, ch, tx * T - camx, sy, ambient, now, view.zoneState || {});
    }
  }

  // dynamic drawables (objects + entities) sorted by occlude-y for depth
  const list = [];
  const add = (yKey, draw) => list.push({ y: yKey, draw });
  const sx = (tx) => tx * T - camx;
  const sy = (ty) => ty * T - camy;

  for (const npc of npcs || []) {
    const dx = sx(npc.x), dy = sy(npc.y);
    if (dx < -32 || dx > W || dy < -32 || dy > H) continue;
    const walk = npc.walking ? now / 170 : 0;
    add((npc.y + 1) * T, () => {
      drawPerson(ctx, dx + T / 2, dy + T * 0.92, T, {
        classId: npc.spriteClass, palette: npc.palette || PAL.skin && { skin: '#c9a07a', hair: '#5a3a2a' },
        facing: npc.facing || 'down', walk, time: now / 1000,
        role: npc.sprite, scale: npc.sprite === 'child' ? 0.85 : 1,
      });
      if (npc.marker) {
        const my = dy - T * 0.4 + Math.sin(now / 400) * T * 0.05;
        ctx.fillStyle = npc.marker === '!' ? '#ffd08a' : '#9fe0d2';
        ctx.fillRect(dx + T / 2 - 2, my, 4, 3);
        ctx.fillStyle = '#000';
        ctx.fillRect(dx + T / 2 - 1, my - 1, 1, 1);
        ctx.fillRect(dx + T / 2, my - 1, 1, 1);
      }
    });
  }

  // player
  add((player.py + 1) * T, () => {
    const px_ = player.px * T + T / 2 - camx;
    const py_ = player.py * T + T * 0.92 - camy;
    const hero = state.party.find((m) => m.id === 'hero');
    const pal = hero ? paletteFor(hero) : { skin: PAL.skin, hair: PAL.hair, cloth: PAL.cloth, accent: PAL.amber };
    drawPerson(ctx, Math.round(px_), Math.round(py_), T, {
      classId: player.classId, palette: pal, facing: player.facing, walk: player.moving ? now / 170 : 0,
      time: now / 1000, scale: 1,
    });
  });

  list.sort((a, b) => a.y - b.y || (a.draw.name || '').localeCompare(b.draw.name || ''));
  for (const d of list) d.draw();

  // lights pass (warm glow only at night/dusk)
  if (view.lights && view.lights.length) {
    drawLights(ctx, W, H, view.lights, now, view.timeCycle || 0.5);
  }

  // vignette
  const edge = ctx.createRadialGradient(W / 2, H / 2, Math.min(W, H) * 0.35, W / 2, H / 2, Math.max(W, H) * 0.8);
  edge.addColorStop(0, 'rgba(0,0,0,0)');
  edge.addColorStop(1, 'rgba(2,4,8,.4)');
  ctx.fillStyle = edge; ctx.fillRect(0, 0, W, H);
}

// distance ridge behind village
function drawDistantRidge(ctx, W, H, now) {
  const t = now / 2000;
  ctx.fillStyle = '#0c0e16';
  ctx.beginPath(); ctx.moveTo(0, H); ctx.lineTo(0, H * .72);
  for (let x = 0; x <= W; x += 20) {
    const y = H * .72 - (Math.sin(x * .02 + t) * 14 + Math.cos(x * .03 - t) * 10);
    ctx.lineTo(x, y);
  }
  ctx.lineTo(W, H); ctx.closePath(); ctx.fill();
  ctx.fillStyle = '#141420';
  ctx.beginPath(); ctx.moveTo(0, H); ctx.lineTo(0, H * .8);
  for (let x = 0; x <= W; x += 26) {
    const y = H * .8 - (Math.sin(x * .015 - t * .5) * 8);
    ctx.lineTo(x, y);
  }
  ctx.lineTo(W, H); ctx.closePath(); ctx.fill();
}

function shade(hex, amt) {
  if (!hex || hex[0] !== '#') return hex;
  const n = parseInt(hex.slice(1), 16);
  const r = clamp((n >> 16) & 255 + amt, 0, 255);
  const g = clamp((n >> 8) & 255 + amt, 0, 255);
  const b = clamp((n & 255) + amt, 0, 255);
  return `rgb(${r | 0},${g | 0},${b | 0})`;
}
const clamp = (v, a, b) => Math.max(a, Math.min(b, v));

function drawLights(ctx, W, H, lights, now, cycle) {
  const brightness = .5 - .5 * Math.cos(cycle * TAU);
  const night = 1 - brightness;
  if (night < .03) return;
  ctx.save();
  ctx.globalCompositeOperation = 'destination-out';
  ctx.fillStyle = `rgba(0,0,0,${Math.min(.7, night * .66)})`;
  ctx.fillRect(0, 0, W, H);
  for (const l of lights) {
    const r = l.r * (1 + Math.sin(now / 700 + l.x) * .02);
    const g = ctx.createRadialGradient(l.x, l.y, 0, l.x, l.y, r);
    g.addColorStop(0, `rgba(0,0,0,${l.strength || .9})`);
    g.addColorStop(.5, `rgba(0,0,0,${(l.strength || .9) * .4})`);
    g.addColorStop(1, 'rgba(0,0,0,0)');
    ctx.fillStyle = g; ctx.beginPath(); ctx.arc(l.x, l.y, r, 0, TAU); ctx.fill();
  }
  ctx.restore();
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  for (const l of lights) {
    if (!l.glow) continue;
    const g = ctx.createRadialGradient(l.x, l.y, 0, l.x, l.y, l.r * .7);
    g.addColorStop(0, withAlpha(l.glow, .18 * night));
    g.addColorStop(1, withAlpha(l.glow, 0));
    ctx.fillStyle = g; ctx.beginPath(); ctx.arc(l.x, l.y, l.r * .7, 0, TAU); ctx.fill();
  }
  ctx.restore();
}

export const TAU2 = Math.PI * 2;

// ── Tile-based world renderer (16-bit JRPG style) ────────────────────────
// 320×180 logical viewport, 16×16 tiles, nearest-neighbour pixels.
// Draw order: background ridge → ground tiles → y-sorted objects & characters
// (FFVI-style depth) → warm light pass → vignette.
import { state } from '../state.js';
import {
  PAL, TILE, VW, VH, hash2, TAU, drawText, pr, lineV, lineH, px, withAlpha,
} from './pixel.js';
import { drawPerson } from './art.js';

const T = TILE;
const tileCache = new Map();

// ── small geometry helpers ───────────────────────────────────────────────
function shade(hex, amt) {
  if (!hex || hex[0] !== '#') return hex;
  const n = parseInt(hex.slice(1), 16);
  const r = clamp((((n >> 16) & 255) + amt), 0, 255);
  const g = clamp((((n >> 8) & 255) + amt), 0, 255);
  const b = clamp(((n & 255) + amt), 0, 255);
  return `rgb(${r | 0},${g | 0},${b | 0})`;
}
const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
function fillCircle(t, cx, cy, r, c) {
  t.fillStyle = c;
  for (let dy = -r; dy <= r; dy++) for (let dx = -r; dx <= r; dx++) {
    if (dx * dx + dy * dy <= r * r) t.fillRect(cx + dx, cy + dy, 1, 1);
  }
}
function fillEllipse(t, cx, cy, rx, ry, c) {
  t.fillStyle = c;
  for (let dy = -ry; dy <= ry; dy++) for (let dx = -rx; dx <= rx; dx++) {
    if ((dx * dx) / (rx * rx) + (dy * dy) / (ry * ry) <= 1) t.fillRect(cx + dx, cy + dy, 1, 1);
  }
}
function fillPoly(t, pts, c) {
  t.fillStyle = c;
  let minX = Infinity, maxX = -Infinity, minY = Infinity, maxY = -Infinity;
  for (const p of pts) { minX = Math.min(minX, p[0]); maxX = Math.max(maxX, p[0]); minY = Math.min(minY, p[1]); maxY = Math.max(maxY, p[1]); }
  for (let py = minY; py <= maxY; py++) {
    const xs = [];
    const n = pts.length;
    for (let i = 0, j = n - 1; i < n; j = i++) {
      const [xi, yi] = pts[i], [xj, yj] = pts[j];
      if ((yi > py) !== (yj > py)) xs.push((xj - xi) * (py - yi) / (yj - yi) + xi);
    }
    xs.sort((a, b) => a - b);
    for (let k = 0; k < xs.length; k += 2) {
      for (let sx = Math.ceil(xs[k]); sx <= Math.floor(xs[k + 1]); sx++) t.fillRect(sx, py, 1, 1);
    }
  }
}

// ── tile art (draws at canvas offset x,y) ────────────────────────────────
function tileGrass(t, x, y, tx, ty) {
  const n = hash2(tx, ty);
  pr(t, x, y, T, T, n > .5 ? PAL.grass : PAL.grassD);
  if (n > .65) {
    pr(t, x + 3 + (tx * 3 % 5), y + 10 + (ty * 2 % 4), 2, 2, PAL.grassL);
    pr(t, x + 10 + (ty * 3 % 4), y + 4 + (tx % 3), 1, 2, shade(PAL.grassD, -25));
  }
  if (n > .85) pr(t, x + 7 + (tx % 2), y + 12, 1, 2, PAL.grassD);
}
function tileTallGrass(t, x, y, tx, ty) {
  tileGrass(t, x, y, tx, ty);
  const n = hash2(tx * 2, ty);
  lineV(t, x + 6, y + 10, 4, shade(PAL.grassD, -15));
  lineV(t, x + 8, y + 11, 3, shade(PAL.grassD, -15));
}
function tileFlowers(t, x, y, tx, ty) {
  const n = hash2(tx * 5, ty);
  pr(t, x, y, T, T, PAL.grass);
  const heads = [];
  if (n > .4) heads.push([x + 4, y + 7]);
  if (n > .6) heads.push([x + 11, y + 5]);
  if (n > .8) heads.push([x + 7, y + 9]);
  for (const [fx, fy] of heads) {
    const hc = (fx + fy * 7) % 2 ? PAL.flower : PAL.flowerL;
    pr(t, fx, fy, 2, 2, hc);
    pr(t, fx + 1, fy + 1, 1, 1, '#5a3a2a');
  }
  pr(t, x + 3 + (tx % 3), y + 13, 1, 2, PAL.grassD);
}
function tileTree(t, x, y, tx, ty) {
  const n = hash2(tx * 1.3, ty * 1.7);
  pr(t, x, y, T, T, PAL.shadow);
  lineV(t, x + 7, y + 10, 6, '#4a3526');
  lineV(t, x + 8, y + 10, 6, '#3a2a22');
  pr(t, x + 6, y + 16, 4, 1, '#3a2a22');
  const leaf = shade(PAL.leaf, Math.round((n - .5) * 14));
  const leaf2 = shade(PAL.leafL, Math.round((n - .5) * 10));
  const cx = x + 8;
  fillCircle(t, cx, y + 4, 5, leaf);
  fillCircle(t, cx + 2, y + 5, 4, leaf);
  fillCircle(t, cx - 2, y + 6, 4, leaf2);
  fillCircle(t, cx, y + 2, 3, leaf2);
  pr(t, cx - 1, y, 2, 2, shade(PAL.leaf, -20));
}
function tileTreeBig(t, x, y, tx, ty) {
  const n = hash2(tx * 7, ty * 11);
  pr(t, x, y, T, T, PAL.shadowD);
  lineV(t, x + 7, y + 12, 4, '#4a3526');
  lineV(t, x + 8, y + 12, 4, '#3a2a22');
  pr(t, x + 6, y + 16, 4, 1, '#3a2a22');
  const leaf = shade(PAL.leaf, Math.round((n - .5) * 14));
  const cx = x + 8;
  fillCircle(t, cx, y + 3, 6, leaf);
  fillCircle(t, cx + 3, y + 4, 5, leaf);
  fillCircle(t, cx - 3, y + 4, 5, leaf);
  fillCircle(t, cx, y, 4, shade(PAL.leafL, 10));
  pr(t, cx - 1, y, 2, 1, shade(PAL.leaf, -20));
  pr(t, cx + 4, y + 3, 1, 1, PAL.leafL);
}
function tilePath(t, x, y, tx, ty) {
  const n = hash2(tx * 2, ty * 3);
