  return new Promise((resolve) => {
    const dlg = $('#dialogue');
    dlg.classList.remove('hidden');
    ui.dialogueOpen = true;
    $('#dlg-choices').classList.add('hidden');
    $('#dlg-choices').innerHTML = '';
