// ── sizing ─────────────────────────────────────────────────────
function resize() {
  const maxW = window.innerWidth;
  const maxH = window.innerHeight;
  let s = Math.min(Math.floor(maxW / LOGICAL_W), Math.floor(maxH / LOGICAL_H), 4);
  if (s < 1) s = 1;
  scale = s;
  viewW = LOGICAL_W;
  viewH = LOGICAL_H;
