import fs from 'fs';

const BASE = 'http://localhost:9222';
let sessionId;

async function req(method, path, body) {
  const opts = { method, headers: { 'Content-Type': 'application/json' } };
  if (body) opts.body = JSON.stringify(body);
  const r = await fetch(BASE + path, opts);
  return r.json();
}
async function cdp(method, params = {}) {
  return req('POST', `/session/${sessionId}/${method}`, params);
}
async function sleep(ms) { return new Promise(r => setTimeout(r, ms)); }

const targets = await req('GET', '/json');
const page = targets.find((t) => t.type === 'page' && t.url.includes('index.html'));
if (!page) throw new Error('no page target');
sessionId = page.id;
console.log('session', sessionId);

await sleep(1500); // boot + first draw

// helper: tap keys
async function key(key, down = true) {
  await cdp('Input.dispatchKeyEvent', { type: down ? 'keyDown' : 'keyUp', key, windowsVirtualKeyCode: key === 'ArrowUp' ? 38 : key === 'ArrowDown' ? 40 : key === 'ArrowLeft' ? 37 : 39 });
}

// walk: tap a direction several times
async function walk(dir, n, gap = 120) {
  for (let i = 0; i < n; i++) {
    await key(dir, true); await key(dir, false); await sleep(gap);
  }
}

await walk('ArrowUp', 7);
await sleep(300);
await cdp('Page.screenshot', { format: 'jpeg', quality: 80 }).then((r) => {
  fs.writeFileSync('/tmp/opencode/s2.jpg', Buffer.from(r.data, 'base64'));
  console.log('saved s2.jpg');
});

import fs from 'fs';

const BASE = 'http://localhost:9222';
let sessionId;

async function req(method, path, body) {
  const opts = { method, headers: { 'Content-Type': 'application/json' } };
  if (body) opts.body = JSON.stringify(body);
  const r = await fetch(BASE + path, opts);
  let text;
  try { text = await r.text(); } catch (e) { text = `<no body: ${e.message}>`; }
  if (!r.ok) throw new Error(`HTTP ${r.status} ${method} ${path}: ${text}`);
  try { return JSON.parse(text); } catch (e) { return text; }
}
async function cdp(method, params = {}) {
  return req('POST', `/session/${sessionId}/${method}`, params);
}
async function sleep(ms) { return new Promise(r => setTimeout(r, ms)); }

(async () => {
  const targets = await req('GET', '/json');
  const page = targets.find((t) => t.type === 'page' && t.url.includes('index.html'));
  if (!page) throw new Error('no page target:\n' + JSON.stringify(targets.map((t) => ({ type: t.type, url: t.url }))));
  sessionId = page.id;
  console.log('session', sessionId, page.url);

  await sleep(2000);

  async function key(key) {
    await cdp('Input.dispatchKeyEvent', { type: 'keyDown', key });
    await cdp('Input.dispatchKeyEvent', { type: 'keyUp', key });
  }
  async function walk(dir, n, gap = 120) {
    for (let i = 0; i < n; i++) { await key(dir); await sleep(gap); }
  }

  await walk('ArrowUp', 7);
  await sleep(300);

  const shot = await cdp('Page.screenshot', { format: 'jpeg', quality: 80 });
  console.log('screenshot keys:', Object.keys(shot));
  const buf = Buffer.from(shot.data, 'base64');
  fs.writeFileSync('/tmp/opencode/s2.jpg', buf);
  console.log('saved', buf.length, 'bytes');
})().catch((e) => { console.error('FATAL', e); process.exit(1); });

import fs from 'fs';

const BASE = 'http://localhost:9515';
let sid;

async function req(method, path, body) {
  const opts = { method, headers: { 'Content-Type': 'application/json' } };
  if (body) opts.body = JSON.stringify(body);
  const r = await fetch(BASE + path, opts);
  const text = await r.text().catch(() => '');
  if (!r.ok) throw new Error(`HTTP ${r.status} ${method} ${path}: ${text}`);
  return text ? JSON.parse(text) : {};
}

async function sleep(ms) { return new Promise(r => setTimeout(r, ms)); }

(async () => {
  const s = await req('POST', '/session', {
    capabilities: { alwaysMatch: { browserName: 'chrome', 'goog:chromeOptions': { args: ['--headless=new', '--disable-gpu', '--no-sandbox', '--window-size=960,540', '--hide-scrollbars'] } } },
  });
  sid = s.value.sessionId;
  console.log('session', sid);
  const { value } = await req('POST', `/session/${sid}/url`, { url: 'http://localhost:1337/index.html' });
  await sleep(2500);

  async function key(key) {
    await req('POST', `/session/${sid}/actions`, {
      actions: [{ type: 'key', id: 'kb', actions: [{ type: 'keyDown', value: key }, { type: 'keyUp', value: key }] }],
    });
  }
  async function walk(dir, n, gap = 150) {
    for (let i = 0; i < n; i++) { await key(dir); await sleep(gap); }
  }

  await walk('ArrowUp', 6);
  await sleep(300);

  const shot = await req('GET', `/session/${sid}/screenshot`);
  fs.writeFileSync('/tmp/opencode/screen.png', Buffer.from(shot.value, 'base64'));
  console.log('saved screen.png');
  await req('DELETE', `/session/${sid}`);
})().catch((e) => { console.error('FATAL', e); process.exit(1); });

