import fs from 'fs';

const BASE = 'http://localhost:9515';
let sid;

async function req(method, path, body) {
  const opts = { method, headers: { 'Content-Type': 'application/json' } };
  if (body) opts.body = JSON.stringify(body);
  const r = await fetch(BASE + path, opts);
  const text = await r.text().catch(() => '');
  if (!r.ok) throw new Error(`HTTP ${r.status} ${method} ${path}: ${text}`);
  return text ? JSON.parse(text) : {};
}
async function sleep(ms) { return new Promise(r => setTimeout(r, ms)); }
const K = { ArrowUp: '\uE013', ArrowDown: '\uE015', ArrowLeft: '\uE012', ArrowRight: '\uE014', Enter: '\uE007', ' ': '\uE00D' };
async function key(k) { await req('POST', `/session/${sid}/actions`, { actions: [{ type: 'key', id: 'kb', actions: [{ type: 'keyDown', value: K[k] }, { type: 'keyUp', value: K[k] }] }] }); }
async function click(css) {
  const { value: el } = await req('POST', `/session/${sid}/element`, { using: 'css selector', value: css });
  await req('POST', `/session/${sid}/element/${el}/click`, {});
}
async function walk(dir, n, gap = 150) { for (let i = 0; i < n; i++) { await key(dir); await sleep(gap); } }

const SAVE = {
  version: 1, started: true, heroName: 'Aren', heroClass: 'vanguard', heroOrigin: 'hearthbound', heroPalette: 0,
  level: 1, gold: 60,
  party: [{ id: 'hero', name: 'Aren', classId: 'vanguard', palette: 0, level: 1, xp: 0, sp: 1, learned: ['shieldBash'], gear: { weapon: 'wornBlade', charm: null }, origin: 'hearthbound', joined: true, hp: 132, mp: 28 }],
  gearOwned: ['wornBlade'], inventory: {},
  flags: { prologueDone: false },
  quests: { locket: { status: 'inactive' }, relief: { status: 'inactive' }, braziers: { status: 'inactive' }, bounty: { status: 'inactive', kills: 0 }, moonpetal: { status: 'inactive' } },
  keys: 0, zone: 'hearthfall', pos: { x: 15, y: 14 }, facing: 'down',
  openedChests: [], takenSparkles: [], litBraziers: [], crystals: [], visited: {}, steps: 0, repelSteps: 0, time: 0, playtime: 0,
  settings: { sound: true, difficulty: 'balanced' }, ngPlus: 0, legacy: false, legacyEnding: null, legacyName: null, legacyClass: null, ending: null, introDone: false,
};

(async () => {
  const s = await req('POST', '/session', {
    capabilities: { alwaysMatch: { browserName: 'chrome', 'goog:chromeOptions': { args: ['--headless=new', '--disable-gpu', '--no-sandbox', '--window-size=960,540', '--hide-scrollbars'] } } },
  });
  sid = s.value.sessionId;
  console.log('session', sid);
  await req('POST', `/session/${sid}/url`, { url: 'http://localhost:1337/index.html' });
  await sleep(1500);

  await req('POST', `/session/${sid}/execute/sync`, {
    script: `localStorage.setItem('emberwake.chronicle.v1', ${JSON.stringify(JSON.stringify(SAVE))}); localStorage.setItem('emberwake.autosave.v1', ${JSON.stringify(JSON.stringify(SAVE))}); return true;`,
    args: [],
  });

  await click('#btn-continue');
  await sleep(1200);

  await walk('ArrowUp', 5);
  await sleep(300);

  const shot = await req('GET', `/session/${sid}/screenshot`);
  fs.writeFileSync('/tmp/opencode/world.png', Buffer.from(shot.value, 'base64'));
  console.log('saved world.png');
  await req('DELETE', `/session/${sid}`);
})().catch((e) => { console.error('FATAL', e); process.exit(1); });

