import fs from 'fs';

const BASE = 'http://localhost:9222';
let sessionId;

async function req(method, path, body) {
  const opts = { method, headers: { 'Content-Type': 'application/json' } };
  if (body) opts.body = JSON.stringify(body);
  const r = await fetch(BASE + path, opts);
  const text = await r.text().catch(() => '');
  if (!r.ok) throw new Error(`HTTP ${r.status} ${method} ${path}: ${text}`);
  return text ? JSON.parse(text) : {};
}
async function cdp(method, params = {}) {
  return req('POST', `/session/${sessionId}/${method}`, params);
}
async function sleep(ms) { return new Promise(r => setTimeout(r, ms)); }

(async () => {
  const targets = await req('GET', '/json');
  const page = targets.find((t) => t.type === 'page' && t.url.includes('index.html'));
  if (!page) {
    // no page yet; start fresh via chromedriver? Instead just report
    throw new Error('no page target on ' + JSON.stringify(targets.map(t => ({type:t.type,url:t.url}))));
  }
  sessionId = page.id;
  console.log('session', sessionId);

  // Install console/error capture before anything else
  await cdp('Runtime.enable');
  await cdp('Runtime.addBinding', { name: 'logErr' });
  await cdp('Runtime.evaluate', {
    expression: `
window.__ERRS=[]; window.onerror=(m,u,l,c,err)=>{window.__ERRS.push(String(m)+(err?(' :: '+err.stack):'')); return true;};
window.onunhandledrejection=(e)=>{window.__ERRS.push('REJECTION: '+String(e.reason));};
    `,
  });
  await cdp('Page.enable');
  const errs = [];
  // poll console via Runtime.consoleAPICalled needs event subscription; simpler: poll window.__ERRS
  await req('POST', `/session/${sessionId}/url`, { url: 'http://localhost:1337/index.html' });
  await sleep(2500);
  const stored = await cdp('Runtime.evaluate', { expression: 'JSON.stringify(window.__ERRS||[])', returnByValue: true });
  console.log('errors after load:', stored.result.value);
  const dbg = await cdp('Runtime.evaluate', { expression: 'JSON.stringify({mode:(window.__dbg&&window.__dbg.mode)||"n/a",hasDbg:!!window.__dbg,hasContinue:!!window.__runContinue})', returnByValue: true });
  console.log('dbg state:', dbg.result.value);
})().catch((e) => { console.error('FATAL', e); process.exit(1); });

