import net from 'net';

const URL = 'ws://127.0.0.1:9222/devtools/page/9389CBEFECEC0729D13A8527698698F4';
const [, hostPort] = URL.split('//');
const [host, port] = hostPort.split(':');
const path = '/devtools/page/9389CBEFECEC0729D13A8527698698F4';

let sock;
let buffer = '';
let id = 0;
const pending = new Map();
const events = [];

function connect() {
  return new Promise((resolve, reject) => {
    sock = net.connect({ host, port: Number(port) }, resolve);
    sock.on('data', (c) => { buffer += c; processBuffer(); });
    sock.on('error', reject);
    sock.on('end', () => { console.log('socket end'); });
  });
}
function processBuffer() {
  // simple: we read HTTP response then websocket frames
  let idx;
  while ((idx = buffer.indexOf('\r\n\r\n')) !== -1) {
    const head = buffer.slice(0, idx);
    buffer = buffer.slice(idx + 4);
    if (head.includes('HTTP/1.1 101')) break;
    // otherwise keep reading (shouldn't happen for upgrade)
  }
  // now websocket frames
  while (buffer.length >= 2) {
    const b0 = buffer.charCodeAt(0), b1 = buffer.charCodeAt(1);
    const fin = b0 & 0x80;
    const opcode = b0 & 0x0f;
    const masked = b1 & 0x80;
    const len = b1 & 0x7f;
    let off = 2;
    let payloadLen = len;
    if (payloadLen === 126) { payloadLen = buffer.charCodeAt(off) << 8 | buffer.charCodeAt(off+1); off += 2; }
    else if (payloadLen === 127) { off += 8; payloadLen = 0; for(let i=0;i<8;i++) payloadLen = (payloadLen*256)+buffer.charCodeAt(off+i); } // approx
    let key;
    if (masked) { key = buffer.slice(off, off+4); off += 4; }
    if (buffer.length < off + payloadLen) break;
    const payload = buffer.slice(off, off+payloadLen);
    buffer = buffer.slice(off + payloadLen);
    let data = payload;
    if (masked) {
      const d = [];
      for (let i = 0; i < payloadLen; i++) d.push(payload.charCodeAt(i) ^ key.charCodeAt(i % 4));
      data = Buffer.from(d);
    } else {
      data = Buffer.from(payload, 'latin1');
    }
    if (opcode === 1) {
      try { events.push(JSON.parse(data.toString('utf8'))); } catch (e) { events.push({ raw: data.toString('utf8').slice(0,200) }); }
    } else if (opcode === 8) {
      console.log('CLOSE');
    }
  }
}
function sendRaw(payloadStr) {
  const payload = Buffer.from(payloadStr, 'utf8');
  const len = payload.length;
  const h1 = 0x80 | 0x01;
  let h2 = len < 126 ? len : 126;
  const header = Buffer.alloc(len < 126 ? 2 : 4 + len);
  header[0] = h1; header[1] = h2;
  if (len >= 126) { header[2] = (len >>> 8) & 0xff; header[3] = len & 0xff; payload.copy(header, 4); } else { payload.copy(header, 2); }
  sock.write(header);
}
function cdp(method, params = {}) {
  return new Promise((resolve, reject) => {
    const i = ++id;
    pending.set(i, { resolve, reject });
    sendRaw(JSON.stringify({ id: i, method, params }));
  });
}
async function run() {
  await connect();
  // handshake
  const key = Buffer.from(Math.random().toString()).toString('base64').trim();
  const req = `GET ${path} HTTP/1.1\r\nHost: ${hostPort}\r\nUpgrade: websocket\r\nConnection: Upgrade\r\nSec-WebSocket-Key: ${key}\r\nSec-WebSocket-Version: 13\r\n\r\n`;
  sock.write(req);
  // wait for 101
  await new Promise(r => { const t = setInterval(() => { if (buffer.includes('HTTP/1.1 101')) { clearInterval(t); r(); } }, 50); setTimeout(r, 3000); });
  // process any buffered frames
  processBuffer();

  await cdp('Runtime.enable');
  await cdp('Log', {}); // no-op; console comes via Runtime
  // install error capture
  await cdp('Runtime.evaluate', {
    expression: `window.__ERRS=[];window.onerror=(m,u,l,c,err)=>{window.__ERRS.push(String(m)+(err?' :: '+String(err.stack):''));return true;};window.onunhandledrejection=(e)=>{window.__ERRS.push('REJ '+String(e.reason));};`,
  });
  // reload page to catch load errors
  await cdp('Page.reload');
  await new Promise(r => setTimeout(r, 2500));
  const errs = await cdp('Runtime.evaluate', { expression: 'JSON.stringify(window.__ERRS||[])' });
  console.log('LOAD ERRORS:', errs.result.value);
  const dbg = await cdp('Runtime.evaluate', { expression: 'JSON.stringify({hasDbg:("__dbg" in window), mode:(window.__dbg&&window.__dbg.mode)||"n/a",hasContinue:(typeof window.__runContinue),titleHidden:!!document.querySelector("#screen-title").classList.contains("hidden")})' });
  console.log('DBG:', dbg.result.value);
  // screenshot
  const shot = await cdp('Page.captureScreenshot', { format: 'jpeg', quality: 80 });
  require('fs').writeFileSync('/tmp/opencode/cdp_screen.jpg', Buffer.from(shot.data, 'base64'));
  console.log('screenshot saved');
  sock.end();
}
run().catch((e) => { console.error('FATAL', e); process.exit(1); });

