import fs from 'fs';

const BASE = 'http://localhost:9515';
let sid;
async function req(method, path, body) {
  const opts = { method, headers: { 'Content-Type': 'application/json' } };
  if (body) opts.body = JSON.stringify(body);
  const r = await fetch(BASE + path, opts);
  const text = await r.text().catch(() => '');
  if (!r.ok) throw new Error(`HTTP ${r.status} ${method} ${path}: ${text}`);
  return text ? JSON.parse(text) : {};
}
async function sleep(ms) { return new Promise(r => setTimeout(r, ms)); }

(async () => {
  const s = await req('POST', '/session', {
    capabilities: { alwaysMatch: { browserName: 'chrome', 'goog:chromeOptions': { args: ['--headless=new', '--disable-gpu', '--no-sandbox', '--window-size=960,540', '--hide-scrollbars', '--disk-cache-size=0', '--media-cache-size=0'] } } },
  });
  sid = s.value.sessionId;
  await req('POST', `/session/${sid}/url`, { url: 'http://localhost:1337/index.html?b=' + Date.now() });
  await sleep(2500);
  // dbg
  const dbg = await req('POST', `/session/${sid}/execute/sync`, {
    script: `return { hasDbg: ('__dbg' in window), titleHidden: !!document.querySelector('#screen-title').classList.contains('hidden'), ready: document.readyState };`,
    args: [],
  });
  console.log('dbg:', JSON.stringify(dbg.value));
  // browser console logs
  try {
    const logs = await req('GET', `/session/${sid}/log`, {});
    // log endpoint needs type param via query: /log?type=browser
    const l2 = await req('GET', `/session/${sid}/log?type=browser`, {});
    console.log('browser logs count:', (l2.value || []).length);
    for (const e of (l2.value || []).slice(0, 20)) console.log('LOG:', e.level, e.message.slice(0, 200));
  } catch (e) { console.log('log fetch err', e.message); }
  const shot = await req('GET', `/session/${sid}/screenshot`);
  fs.writeFileSync('/tmp/opencode/loadstate.jpg', Buffer.from(shot.value, 'base64'));
  console.log('screenshot saved');
  await req('DELETE', `/session/${sid}`);
})().catch((e) => { console.error('FATAL', e); process.exit(1); });

